programs.sol:
"""A sparse approximation of the component's larger, recognizable responses.

Predict negative contributions on source-code openings, URL separators,
thought-opening acknowledgements, stock prose, and a few descriptor classes.
Distinguish a few pronoun uses of 'one'; keep zero elsewhere. These are
training-calibrated tendencies, not a complete reconstruction.
Track document starts, the preceding token, and thought-opening state.
"""
READS = ()

IMPORTANCE = frozenset('key main crucial critical important significant vital '
                       'essential integral central fundamental'.split())
COMPLEXITY = frozenset('various diverse myriad numerous intricate complex '
                       'complicated interconnected'.split())
EMPHATIC = frozenset('remarkable profound powerful unique intriguing quaint '
                     'stunning breathtaking innovative vibrant'.split())

CODE_OPENERS = frozenset(('package', '#include', '#pragma', '//', '/*', '/**',
                          '"""', "'''"))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, False)
    _, previous, position, thought = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    value = 0.0
    if position == 0 and (word in CODE_OPENERS or word.startswith('/*')):
        value = -0.677
    elif position == 0 and lower == 'one':
        value = -0.646
    elif word == '<think>':
        value = -0.076
    elif word == '</think>':
        value = 0.091
    elif thought and lower == 'okay':
        value = -0.233
    elif thought and lower == 'alright':
        value = -0.14
    elif lower == 'of' and (previous.strip() == 'One' or prev == 'world'):
        value = -0.171
    elif lower == 'seem' and prev in {'may', 'might'}:
        value = -0.476
    elif lower == 'become' and prev in {'has', 'have'}:
        value = -0.163
    elif lower == 'come' and prev in {'has', 'have'}:
        value = -0.186
    elif token == '://':
        value = -0.211
    elif lower == 'one':
        if prev == 'no':
            value = -0.114
        elif prev in {'which', 'each', 'any', 'every'}:
            value = -0.099
        elif word == 'One' and ('.' in previous or '\n' in previous):
            value = -0.067
        elif prev == ',':
            value = -0.039
    elif token.startswith(' '):
        if lower in IMPORTANCE:
            value = -0.045
        elif lower in COMPLEXITY:
            value = -0.025
        elif lower in EMPHATIC:
            value = -0.063
    if word == '<think>':
        thought = True
    elif word:
        thought = False
    return (doc, token, position + 1, thought), value

"""Negative responses to numeric suffixes of technical names.

The largest responses mark bit widths (int32, float64), vector dimensions
(vec3), and numbers in encoding or version names. Ordinary text is near zero.
Only a short trailing text buffer is carried, reset at document boundaries.
This approximation deliberately leaves unrelated word-pair responses out.
"""
import re

READS = ()

# Completed bit widths share a strong response across full type names.
BIT_WIDTHS = {'8': -8.0, '16': -8.8, '32': -10.5, '64': -11.2}
SHORT_WIDTHS = {'16': -4.0, '32': -6.4, '64': -7.3}


def number_response(before, digit):
    match = re.search(r'([A-Za-z_]*)(-?)([0-9]*)$', before)
    name, separator, digits = match.groups()
    number = digits + digit
    low = name.lower()
    tail = name.rsplit('_', 1)[-1]
    short = tail if tail in {'i', 'u', 'f', 's'} else ''
    # A letter embedded in a hexadecimal identifier is not a scalar type.
    if short == 'f' and match.start() and before[match.start()-1].isalnum():
        short = ''

    # Explicit integer and floating-point types, including CamelCase names
    # such as ToInt32 and Float64.
    full_type = tail.lower() in {'int', 'uint', 'float', 'bfloat', 'datetime'}
    full_type |= name.endswith(('Int', 'Uint', 'UInt', 'Float'))
    if full_type and not separator:
        if low == 'datetime' and number == '64':
            return -8.0
        if number in BIT_WIDTHS:
            return BIT_WIDTHS[number]
        if not digits:
            if digit == '1':
                return -1.7
            if digit == '3':
                return -4.4 if low != 'uint' else -2.7
            if digit == '6':
                return -7.5 if low == 'float' else -5.6
        if len(number) == 2:
            return -4.0 if digit == '8' else -1.7
        return -0.1

    # Compact type notations in Rust, WebAssembly, and shader languages.
    if short and not separator:
        if number in SHORT_WIDTHS:
            return SHORT_WIDTHS[number] * (0.4 if short == 's' else 1.0)
        if number == '18' and short == 'i':  # i18n, internationalization
            return -4.7
        if not digits:
            if digit == '8':
                return -3.7 if short == 'u' else -1.0
            if digit == '6':
                return -2.7 if short in {'i', 'u'} else -0.4
            if digit == '3':
                return -1.5 if short != 'f' else -0.7
            if digit == '1':
                return -0.4
        return 0.0

    if low.endswith(('vec', 'vector')) and not digits:
        return {'2': -6.1, '3': -6.0, '4': -8.1}.get(digit, 0.0)

    # Common encodings and technical names whose number is part of the name.
    if low in {'utf', 'utf_'} and number == '8':
        return -3.0 if separator or low.endswith('_') else -7.3
    if low == 'base':
        return {'6': -1.7, '64': -6.6, '58': -2.9}.get(number, 0.0)
    if low == 'sha' and number == '256':
        return -5.8
    if tail.lower() == 'web' and not digits and digit in '23':
        return -5.8
    if low in {'sqlite', 'urllib'} and not digits and digit in '23':
        return -4.1 if low == 'sqlite' else -3.0
    if low == 'uuid' and number == '4':
        return -6.0
    if low == 'ipv' and number == '6':
        return -6.0
    if low in {'win', 'user', 'crc'} and number == '32':
        return -3.7
    if low == 'amd' and number == '64':
        return -3.5

    # Version numbers and multimedia format numbers are weaker triggers.
    if name.endswith('v') and not digits:
        return {'1': -0.6, '2': -1.2, '3': -1.7,
                '4': -2.1, '6': -1.3, '8': -1.3}.get(digit, 0.0)
    if low.endswith('mp') and not digits:
        return {'3': -0.9, '4': -1.8}.get(digit, 0.0)
    if name.endswith('_') and number in SHORT_WIDTHS:
        return SHORT_WIDTHS[number] * 0.28
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        value = number_response(before, token)
    return (doc, (before + token)[-64:]), value

"""A surface-spelling detector for micro-, mu, and microorganisms.

Micro- spellings give negative pulses, especially when split into short
pieces. Microsoft is weaker; three whole-token micro- compounds are quiet.
A recent Greek-letter run quiets mu; its symbol and LaTeX name are active
elsewhere.
There are also micro-RNA, tiny/germ characters, and two positive word
completions (microphone and Chinese 'breeze'). Title-header colons and
paired middle dots are separate surface triggers. Other text predicts zero.
"""
import re
import unicodedata

READS = ()
ROOTS = ('micro', 'mikro', 'микро', 'мікро', 'μικρο', 'マイクロ')


def predict_token(carry, token, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    token = unicodedata.normalize('NFKC', token)
    lower = token.lower()
    text = lower.strip()
    joined = tail + lower
    value = 0.0
    if text == ':' and (tail == 'title' or tail.endswith('<|endoftext|>title')):
        value = -4.6
    elif text in ('风', '風') and tail.endswith('微'):
        value = 5.6
    elif text == '微':
        value = -4.5
    elif text in ('菌', '균'):
        value = -3.9
    elif text == '··':
        value = -2.6
    elif text == 'μ':
        greek_prose = re.search(r'[α-ω]{3}', tail[-24:])
        value = 0.0 if greek_prose or token.strip() == 'Μ' else -4.3
    elif text == 'mu':
        value = -4.7 if previous.endswith('\\') else -0.5
    elif 'microsoft' in lower:
        value = -1.9 if 'Microsoft' in token else -3.6
    elif text in ('microphone', 'microwave', 'microseconds'):
        value = 0.0
    elif any(root in lower for root in ROOTS):
        if len(text) <= 6:
            value = -5.6
        elif len(text) <= 9:
            value = -4.0
        else:
            value = -3.8
    elif not lower[:1].isspace():
        # Look only at letters in the current word, never across a space.
        match = re.search(r'[^\W\d_]+$', joined)
        word = match[0] if match else ''
        old = re.search(r'[^\W\d_]+$', tail)
        before = old[0] if old else ''
        root = next((r for r in ROOTS if r in word), None)
        if root and root not in before:
            if before.endswith('m'):
                value = -6.1
            elif word.endswith(('micron', 'microns')):
                value = -3.5
            elif len(text) <= 3:
                value = -10.6
            elif len(text) <= 7:
                value = -6.6
            else:
                value = 0.0
            if 'microsoft' in word:
                value = -3.7
        elif root and before.endswith(root):
            if text == 'phone':
                value = 2.2
            elif text in ('rn', 'rna'):
                value = -7.9
            elif len(text) == 1 and text.isascii():
                value = -6.5
            else:
                value = -2.6 if len(text) <= 3 else -1.4
        elif text in ('r', 'rn', 'rna') and before.endswith('mi'):
            value = -3.7 if text == 'r' else -4.9
        elif any(word.endswith(r[:-1]) and not before.endswith(r[:-1]) for r in ROOTS):
            value = -5.0
    if value == 0.0 and text in ('мик', 'мік', 'mik'):
        value = -3.7
    elif value == 0.0 and text == 'mic':
        value = -0.6
    return (doc, joined[-48:], lower), value


def step(carry, prefix, upstream):
    return predict_token(carry, prefix.token_strings[-1], prefix.document_ids[-1])

programs.haiku:
"""The "micro" detector: negative wherever the text spells the prefix micro-.

The program follows the letters of the word being written, and fires where "micro" appears:
  * on a whole token carrying it, such as " micro", "Micro", " microscopy", " Microsoft"
    (about -4.5);
  * on the piece of a split word that completes it, as in "mic" + "rol" ("microl"),
    "mic" + "rop" ("microp"), "antim" + "icro" (about -7);
  * weakly (about -1.5) on later pieces of a word that already contains "micro".
It also fires on the micro sign µ and on Greek μ after a number or unit ("25 µg", "20 μM")
(about -4.5), on LaTeX \\mu (about -4.5), and on the "R" of miRNA ("mi" + "R", about -4).
Everyday words that only look like micro- (microphone, microwave, microseconds) do not fire.
Everything else predicts 0.
"""

import re

READS = ()

STEMS = ("micro", "микро")  # the stem in Latin and Cyrillic script
EVERYDAY = ("microphone", "microwave", "microseconds")

WHOLE_MICRO = -4.5  # a token carrying "micro" itself
PIECE_MICRO = -7.0  # the piece of a split word that completes "micro"
AFTER_MICRO = -1.5  # later pieces of a word that already contains "micro"
MU_UNIT = -4.5  # micro sign, or Greek mu after an ASCII number or unit
LATEX_MU = -4.5  # \mu in math
MIRNA = -4.0  # "R" of miRNA, after "mi"


def _ascii(text):
    return all(ord(c) < 128 for c in text)


def _has_stem(text):
    return any(stem in text for stem in STEMS)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    new_doc = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if new_doc:
        prev = ""
    word = "" if (carry is None or new_doc) else carry
    # letters of the word so far, lowercased: the carry for the next position
    word_after = re.search(r"[^\W\d_]*$", word + token.lower()).group(0)

    if bare.lower() in EVERYDAY:
        value = 0.0
    elif _has_stem(word_after) and not _has_stem(word):
        value = WHOLE_MICRO if _has_stem(token.lower()) else PIECE_MICRO
    elif _has_stem(word_after):
        value = AFTER_MICRO
    elif bare == "µ" or (bare == "μ" and prev and _ascii(prev.strip())):
        value = MU_UNIT
    elif bare == "mu" and prev.endswith("\\"):
        value = LATEX_MU
    elif bare.startswith("R") and word == "mi":
        value = MIRNA
    else:
        value = 0.0
    return word_after, float(value)

programs.sol:
"""Detect abstract/summary labels and neighboring bibliographic formatting.

The abstract word family is strongest as a heading, weaker in prose, and
usually suppressed in code. Translated summary labels and citation links
also respond. These are spelling cues, not semantic disambiguation.
A short-lived state models following delimiters or words.
Separate rules cover a few document-opening and dotted-separator effects.
"""
import re

READS = ()
INITIAL_FORMS = {
    "\t": 1.4,
    "\\n": 1.26,
    "\n": 0.55,
    "\n\n": 0.4,
    "#ifndef": 1.94,
    "#define": 1.37,
    "class": -1.55,
    "package": 0.72,
    "using": 0.72,
}
CODE_WORDS = r"\b(?:extends|implements|public|private|protected|raise|new)\s*$"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail, kind, strength = 0, "", "", 0.0
    else:
        _, n, tail, kind, strength = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    text = tail + token
    line = tail.rsplit("\n", 1)[-1]
    at_heading = not line.strip(" \t#*-.|")
    value, next_kind = -0.0005, ""

    # Propagate heading responses through nearby delimiters or the first word.
    if kind == "abstract":
        if word.startswith((":", ".")):
            value = strength * (1.2 if word == "." else 0.85)
        elif token == "}":
            value = 0.7
        elif token.isspace():
            value = strength * (0.55 if "\n\n" in token else 0.35)
        elif token[:1].isspace():
            value = 0.2 * strength
    elif kind == "schema" and word == ":":
        value, next_kind = 4.5, "schema_value"
    elif kind == "schema_value" and word in {"'", '"'}:
        value = 4.5
    elif kind == "bracket" and word == "】":
        value, next_kind = 0.7 * strength, "bracket_close"
    elif kind == "bracket_close" and word in {":", "："}:
        value = 0.7 * strength
    elif kind.startswith("chinese") and word in {":", "："}:
        value = 5.0 if kind == "chinese_first" else (
            2.0 if kind == "chinese_heading" else 0.3
        )

    if re.search(r"abstract\Z", text, re.I):
        attached = not token[:1].isspace() and (
            tail[-1:].isalnum() or tail[-1:] in {".", "/", "_"}
        )
        code = attached or re.search(CODE_WORDS, tail)
        if tail.endswith("{") and "begin" in tail[-20:]:
            value, next_kind = 4.5, "abstract"
        elif word.isupper():
            value, next_kind = 3.4, "abstract"
        elif code:
            value = -0.18
        elif word == "Abstract":
            academic = re.search(
                r"Publisher|University|E-mail|@|Editor|Submitted|"
                r"Publication|draft|Technical", tail
            )
            value = 3.3 if at_heading else (3.6 if academic else 1.2)
            if line.strip() == "|":
                value = 4.8
            elif tail.rstrip().endswith("|"):
                value = 3.6
            next_kind = "abstract"
        elif at_heading and not line:
            value, next_kind = 2.0, "schema"
        else:
            value = -0.13
            if re.search(r"Show full|\[\s*$|\b[Ss]ee\s*$", tail):
                value = 2.1
            elif tail[-1:] in {"'", '"'}:
                value = 1.5
            elif tail.lower().endswith("in the"):
                value = 1.0
    elif re.search(r"abstr(?:a)?\Z", text, re.I):
        value = 3.0 if text.lower().endswith("abstra") else 2.0
    elif word == "摘要":
        value = 3.4
        next_kind = "chinese_heading" if at_heading else "chinese_inline"
        if tail.endswith("【"):
            value = 6.0 if not line[:-1].strip() else 4.0
            next_kind = "bracket"
        elif n == 0:
            value, next_kind = 5.6, "chinese_first"
    elif text.endswith("초록"):
        value = 4.1
    elif re.search(r"\b(?:résumé|resumen|resumo)\Z", text, re.I):
        label = re.search(r"\w+\Z", text)[0]
        value = 4.0 if label[0].isupper() else (
            1.9 if label.lower() == "résumé" else 1.3
        )
    elif word == "Scholar" and tail.endswith("Google"):
        if re.search(r"(?:Article|PubMed)Google$", tail):
            value = 1.9
        elif tail[-7:-6].isalpha() or tail[-7:-6] in {"[", "."}:
            value = 1.1
        elif re.search(r"doi|\b(?:19|20)\d{2}\b", line):
            value = 0.75
    elif word == "Received" and (token[:1].isspace() or at_heading):
        academic = re.search(r"author|University|School|China|Germany|doi", tail, re.I)
        value = 3.3 if academic else (1.2 if at_heading else 0.35)
    elif word == "received":
        value = -0.2
    elif word.lower() == "summary":
        value = 0.5 if at_heading or word.isupper() else -0.04

    if word and set(word) == {"·"} and len(word) >= 2:
        value = 1.17
    if n == 0:
        value = INITIAL_FORMS.get(token, value)
    if word == "#include":
        value = 0.22 if n == 0 else -0.18
    elif word == "#define" and n:
        value = -0.13
    return (doc, n + 1, text[-200:], next_kind, value), float(value)

programs.haiku:
"""The word "abstract", and the first token of each document.

The component reads the word "abstract" in its many spellings: an "Abstract" heading, the
"AB" + "STRACT" split, the fragment "str" that completes "abstr" in other languages
(abstrakt, abstrait), the Chinese 摘要 and Korean 초록 (both "abstract"), and the French or
Spanish "résumé" and "resumen" ("summary"). It is weaker on other section headings of a
paper ("Summary", "Introduction", "Conclusion"), and on "Scholar" in "Google Scholar".

At the first token of a document, which the model reads with no earlier context, its value
depends on what kind of token that is: a function word after a space (" the", " of", " my")
is negative, a line break, digit or markup token is positive. Everywhere else it predicts 0,
the component's typical value. Only the text so far is read.
"""

READS = ()

FUNCTION_WORDS = set(
    "the a an of to in on at for and or is are was were with from by my your his her its "
    "our their this that as be it not can will".split()
)
SECTION_HEADINGS = {"Summary", " SUMMARY", "Introduction", "Conclusion", " Conclusion", "BACKGROUND"}


def document_start_value(tok):
    word = tok.strip()
    if tok.startswith("<|"):
        return 0.25
    if tok[:1] in ("\n", "\r"):
        return 0.5
    if tok[:1] == "#":
        return -0.15
    if word.lower() in FUNCTION_WORDS:
        return -0.24 if tok[:1] == " " else 0.0
    if tok[:1] == " " and word[:1].islower():
        return -0.09
    if word[:1].isdigit():
        return 0.2
    if word[:1].isupper():
        return 0.12
    if word[:1].islower():
        return 0.14
    return 0.0


def abstract_value(tok, before, prev):
    """How strongly this token spells or heads "abstract", given the text before it."""
    heading = not prev[-1:].isalpha()          # starts a line or follows punctuation
    if tok in ("摘要",):
        return 4.3                              # Chinese: abstract
    if tok == "록" and before.endswith("초"):
        return 4.0                              # Korean 초록: abstract
    if tok.lower() in ("str", "stra", "stract") and before.lower().endswith("ab"):
        return 3.0                              # "AB" + "STRACT", "Ab" + "str" + "akt"
    if tok in ("Abstract", "ABSTRACT") and heading:
        return 3.0
    if tok == " Abstract" and heading:
        return 1.5
    if tok == "é" and before.lower().endswith("résum"):
        return 1.6                              # French: résumé
    if tok == " Scholar" and before.endswith("Google"):
        return 1.0                              # "Google Scholar" in a reference list
    if tok in SECTION_HEADINGS:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, document_start_value(tok)
    before = prefix.text_prefixes[-2]
    prev = prefix.token_strings[-2]
    return carry, abstract_value(tok, before, prev)

"""Document openers: the component writes a value on the first token of each document.

At the first token of a document (no earlier tokens to attend to), the component's
activation is a fixed function of the token itself. Roughly:
  - code and markup openers (import, package, #include, def, function, #, ...): large positive
  - common sentence-opening words (The, How, What, In, A, I, ...), digits, chat markers: positive
  - leading-space words that continue a sentence: negative, most for modals and negations
    (can, could, don't ...), mildly positive for prepositions such as " to", " in", " on"
  - lowercase word fragments: slightly negative; broken UTF-8 bytes: negative
Everywhere else (the rest of every document) it is ~0, which is also the mean.
"""
READS = ()

CODE_KEYWORDS = {"import", "package", "from", "def", "class", "const", "int", "var",
                 "function", "export", "type", "string"}
CODE_MARKERS = {"#include", "#!/", "/*", "**", '"""', "#", "##", "###", "//", "--"}
SENTENCE_OPENERS = {"The", "A", "An", "In", "On", "How", "What", "Why", "When", "Where", "Who",
                    "I", "It", "This", "We", "You", "My", "Our", "If", "As", "For", "To",
                    "Question", "Welcome", "New", "Here", "There", "Yes", "No", "Hello", "Thank"}
MODALS_AND_NEGATIONS = {" can", " could", " might", " will", " would", " should", " must",
                        " may", " don", " didn", " doesn", " isn", " wasn", " couldn",
                        " wouldn", " shouldn", " hadn", " haven", " won", " aren"}
PREPOSITIONS = {" to", " in", " on", " for", " at"}


def opener_value(s):
    if s == "" or "�" in s:
        return -1.8
    if s.startswith("<|"):
        return 1.9
    if s in CODE_KEYWORDS:
        return 5.0
    if s in CODE_MARKERS:
        return 3.0
    if s in MODALS_AND_NEGATIONS:
        return -3.5
    if s in PREPOSITIONS:
        return 1.0
    if s in SENTENCE_OPENERS:
        return 2.5
    c = s[0]
    if c == " ":
        return -0.2
    if c.isdigit():
        return 1.85
    if c.isupper():
        return 0.6 if s.isalpha() else 0.0
    if c.islower():
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    is_start = prefix.position == 0 or doc[-1] != doc[-2]
    if not is_start:
        return None, 0.0
    return None, opener_value(prefix.token_strings[-1])

"""Fires on the spelled sound 'uk' or 'uc' (u followed by k or c), in any script (anyascii
transliterates Cyrillic and others to Latin letters first). It is strongest when the newest
token is itself 'uk' (UK, Muk, Suk, cuk); a fragment that completes 'uk' after an earlier piece
(Sou|k, nau|k) is weaker, 'uc' weaker still. Cyrillic у+ч ('uch') is weak. ' Kingdom' (as in
United Kingdom) and other tokens containing 'uk' are weakly positive; u+h and u+z push slightly
negative. Everything else is 0.
"""
from anyascii import anyascii
import re

READS = ()
LETTERS = re.compile(r"[a-z]+")


def letters(text):
    return "".join(LETTERS.findall(anyascii(text).lower()))


def step(carry, prefix, upstream):
    newest = letters(prefix.token_strings[-1])
    if not newest:
        return carry, 0.0
    tail = letters(b"".join(prefix.token_bytes[-3:]).decode("utf-8", "ignore"))
    if tail.endswith("uk"):
        return carry, 3.7 if newest == "uk" else 1.75
    if tail.endswith("uc"):
        return carry, 1.5 if newest == "uc" else 0.8
    if tail.endswith("uch") and not prefix.token_strings[-1].isascii():
        return carry, 1.0
    if tail.endswith(("uh", "uzh")):
        return carry, -0.56
    if tail.endswith("uz"):
        return carry, -0.3
    if newest == "kingdom":
        return carry, 2.4
    if "uk" in newest:
        return carry, 0.5
    return carry, 0.0

