"""Recognize locative compounds and line/section boundaries.

Here-/there- compounds receive positive values, especially when completed
across tokens. Bare newlines after short headings or chat role names receive
negative values. Ordinary text stays near zero. A short text tail is kept
to recognize the current word and line; document changes reset it.
Ongoing user separators also depend on recent tool markup and non-ASCII letters.
Smaller spelling rules cover selected word-internal r/d/n syllables and
Greek technical roots. The initial Title: marker and repeated middle dots
have separate values. This is an approximation, not a single semantic topic.
"""
import re

READS = ()

# Strengths for completions of the old locative adverbs.
THERE_ENDINGS = {
    'on': 8.7, 'to': 8.2, 'through': 8.1, 'of': 7.1,
    'unto': 6.8, 'for': 6.5, 'from': 6.4, 'between': 4.9,
    'into': 3.5, 'upon': 3.1, 'after': 1.8, 'about': 1.6,
    'by': 1.4,
}
HERE_ENDINGS = {
    'of': 6.5, 'to': 5.1, 'under': 5.2,
    'with': 2.6, 'in': 0.9, 'after': 0.4,
}
WHOLE_COMPOUNDS = {
    'thereof': 3.2, 'therein': 4.0, 'hereby': 1.45, 'herein': 0.53,
}
SECTIONS = set('''abstract introduction background methods methodology
materials results discussion conclusion conclusions references bibliography
history reception notes footnotes demographics geography population overview
summary acknowledgments acknowledgements contents recommendations'''.split())


def predict(tail, token, position):
    if token in ('\n', '\n\n'):
        line = re.split(r'\n|<\|endoftext\|>|<\|im_start\|>', tail)[-1]
        label = line.strip()
        lower = label.lower()
        if label == 'user':
            recent = tail.rsplit('<|endoftext|>', 1)[-1]
            if tail == 'user':
                return -2.5
            if '<|im_end|>' not in recent and position < 5:
                return -0.54
            context = tail[-200:]
            letters = [c for c in context if c.isalpha()]
            non_ascii = sum(not c.isascii() for c in letters) / max(1, len(letters))
            tool = '<tool_call>' in context or '</tool_call>' in context
            return -1.7 - 0.6 * non_ascii + 0.4 * tool
        if label == 'assistant':
            return -0.08
        if label in ('<tool_call>', '<tool_response>'):
            return -0.27
        if lower == 'question' and position <= 2:
            return -10.4
        if lower in ('question', 'solution', 'explanation', 'quiz'):
            return -4.7
        if lower in ('views', 'likes', 'shares'):
            return -4.5
        if lower in ('replies', 'worksheet', 'documents'):
            return -2.6
        if lower in SECTIONS:
            return -1.4
        if label.isnumeric():
            return -0.4
        if not label:
            return 0.3
        if len(label) == 1:
            return -0.5
        if label.startswith('#') and len(label) < 30:
            return -0.6
        if (label[0].isupper() and len(label) <= 20
                and not line.startswith((' ', '\t'))):
            if label.isalpha() and len(label) <= 15:
                return -1.1
            if len(label.split()) <= 2 and not re.search(r'[.!?;:{}=()<>]', label):
                return -0.35
        return 0.02

    chunk = token.strip()
    if token == ':' and tail in ('Title', '<|endoftext|>Title'):
        return 5.05
    if token == '<|im_start|>' and (position == 0 or tail.endswith('<|endoftext|>')):
        return -0.36
    if len(token) > 1 and set(token) == {'·'}:
        return -1.0
    if not chunk.isascii() or not chunk.isalpha():
        return 0.0

    match = re.search(r'[A-Za-z]+$', tail + token)
    word = match[0] if match else ''
    lower = word.lower()
    if lower in WHOLE_COMPOUNDS and chunk.lower() == lower:
        before = (tail + token)[:-len(word)].rstrip()
        if lower == 'thereof' and before.lower().endswith('lack'):
            return 0.3
        return WHOLE_COMPOUNDS[lower]
    if lower == 'thereby' and chunk.lower() == lower:
        before = (tail + token)[:-len(word)].rstrip()
        previous = re.search(r'[A-Za-z]+$', before)
        passive = previous and previous[0].lower().endswith(('ed', 'en'))
        return 6.0 if passive else 0.5
    # Incomplete prefixes of therethrough and thereto also respond.
    if lower == 'thereth':
        return 4.5
    if len(word) > len(chunk) and not token[0].isspace():
        if lower.startswith('there'):
            return THERE_ENDINGS.get(lower[5:], 0.0)
        if lower.startswith('here'):
            return HERE_ENDINGS.get(lower[4:], 0.0)
        # Productive geometric and English place-name endings.
        if lower.endswith(('hedron', 'hedrons', 'hedra')):
            return 3.5
        # Related r/d/n syllable completions, including Greek technical roots.
        stem = word[:-len(chunk)]
        ending = chunk.lower()
        if ending in ('ron', 'rons') and stem.lower().endswith('d'):
            return 2.7
        if ending == 'od' and stem.lower().endswith('er'):
            return 2.5
        if ending in ('on', 'ons') and stem[-1].lower() in 'dt':
            return 1.0 if word[0].isupper() else 0.25
        if lower.startswith('ather') and ending in ('ogenic', 'ectomy'):
            return 3.3
        if lower in ('threo', 'threon'):
            return 3.0
        if word[0].isupper():
            if ending in ('don', 'erton'):
                return 3.8
            if ending == 'orne' and stem.lower().endswith('th'):
                return 3.0
            if ending == 'ton':
                return 2.0 if lower.endswith('ington') else 0.5
    if word == 'ther' and chunk == word:
        return 2.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    value = predict(tail, token, position)
    return (doc, (tail + token)[-600:], position + 1), value

"""Chinese writing-template constructions, with sparse formatting side rules.

Respond to requests for a written piece, familiar composition names, editorial
collection introductions, and numbered example headings. Ordinary text is nearly
silent. Separate rules cover slide labels and certain document-opening forms.
Examples are 写一篇 ('write an article'), 自我鉴定 ('self-evaluation'),
and 小编...整理 ('the editor collected...'). A separate phrase rule covers
转眼 ('in a blink'), and long middle-dot runs get a negative response.
Spelling and split UTF-8 characters are normalized; context resets per document.
This is a sparse approximation, not an account of the small lexical fluctuations.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_converter = OpenCC('t2s')
normalize = lru_cache(maxsize=4096)(_converter.convert)
NUMBER = r'[0-9一二三四五六七八九十百零〇两]'
GENRE = (r'(?:作文|工作总结|工作计划|教学计划|述职报告|实习报告|'
         r'(?:演讲|发言|竞选|加油)稿|自我(?:介绍|鉴定)|'
         r'(?:读后|观后)感|心得(?:体会|感悟)|策划书|教案|'
         r'祝福语|语录|简历|思想汇报|合同书)')
LABEL = r'(?:' + GENRE + r'|范文)'
EDITOR = r'小编(?:为(?:大家|您|你))?(?:精心)?'
INTRO = r'(?:下面|以下)是[^，。！？\n]{0,12}'
EXAMPLE = r'(?<![一二三四五六七八九十百零〇两这那每本该此几各多])篇\s*'


def response(token, history, position):
    value = -0.002
    if token == '鉴定' and history.endswith('自我'):
        value = 1.7
    elif token == '计划' and history.endswith('教学'):
        value = 2.0
    elif token == '书' and re.search(r'计划$|策划$|合同$', history):
        value = 3.5
    elif token == '稿' and re.search(r'演讲$|发言$', history):
        value = 2.5
    elif token == '感' and re.search(r'读后$|观后$', history):
        value = 1.2
    elif token == '文' and history.endswith('文言'):
        value = 0.8
    elif token == '报告' and re.search(r'实习$|述职$', history):
        value = 1.6
    elif token == '一篇' and history.endswith('写'):
        value = 1.2
    elif token == '一份':
        value = 1.2 if history.endswith('写') else 0.35
    elif token == '眼' and history.endswith('转'):
        value = 2.1
    elif token == '间' and history.endswith('转眼'):
        value = 1.7

    # The standard introduction to material collected by a website editor.
    if token.endswith('小编') and re.search(INTRO + r'小编$', history + token):
        value = 4.7
    elif token in ('整理', '收集', '搜集') and re.search(EDITOR + '$', history):
        strong = re.search(INTRO + EDITOR + '$', history)
        value = 6.5 if strong else 2.2
    elif token == '的' and re.search(EDITOR + r'(?:整理|收集|搜集)$', history):
        value = 5.5
    elif token == '阅读' and re.search(r'欢迎(?:大家(?:分享)?)?$', history):
        value = 2.4
    elif token == '参考' and re.search(r'供(?:大家)?$', history):
        value = 1.2

    line = history.rsplit('\n', 1)[-1]
    # Distinguish "example 4" from "write one 400-word article".
    if re.fullmatch(NUMBER, token):
        if re.search(EXAMPLE + '$', line):
            value = 10.5
        elif re.search(EXAMPLE + NUMBER + r'{1,2}$', line):
            value = 5.0
        elif history.endswith('写一篇'):
            value = 0.6
        elif re.search(LABEL + r'[【（(]?$', line):
            value = 5.0
        elif re.search(GENRE + NUMBER + r'{1,2}$', line):
            value = 0.7
    elif token.strip() == '篇':
        if re.search(r'第' + NUMBER + r'+$', line):
            value = 4.5
        elif re.search(LABEL + r'\s*' + NUMBER + r'*$', line):
            value = 5.0
        elif re.search(NUMBER + '$', line):
            value = 2.6
    elif token == '范文' or (token == '文' and history.endswith('范')):
        stem = line[:-1] if token == '文' else line
        value = 4.2 if re.search(GENRE + '$', stem) else 2.0
    elif token in ('\n', '：\n', ':\n', '】', '）', ')', ')\n'):
