                 r'[ 范文【】（）()字精选第篇0-9一二三四五六七八九十]{0,15}$')
        example_end = (r'^[^，。！？：；,.!?;]{0,70}(?:' + EXAMPLE +
                       NUMBER + r'+|第' + NUMBER + r'+篇)[】）)]*$')
        if re.search(title, line) or re.search(example_end, line):
            numbered = re.search(NUMBER + r'[篇】）)]*$', line)
            value = 3.6 if numbered else 1.0

    if token == ' transcript' and history.endswith(' Presentation'):
        value = 0.95
    elif token == ' Presentation' and history.endswith('PPT'):
        value = 0.75

    # Formatting effects at the beginning of a document.
    if position == 0:
        if token == 'Title':
            value = 1.04
        elif token in ('def', 'int'):
            value = 1.27
        elif token == ' //':
            value = 1.42
        elif token == '//\n':
            value = 3.3
        elif token == ' #':
            value = 1.53
        elif token == '     ':
            value = 0.75
        elif token == '\r':
            value = 1.66
        elif token == '<|endoftext|>':
            value = 1.13
    elif position == 1:
        if history == 'Title' and token == ':':
            value = 1.19
        elif history == '1' and token == '2':
            value = -2.15
    if token == '··' and history.endswith('··' * 5):
        value = -0.895
    if token == '\r' and history and set(history) == {'\r'}:
        value = 1.66
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw, history, position = b'', '', 0
    else:
        _, raw, history, position = carry
    # A four-byte tail suffices to finish an incomplete UTF-8 character.
    previous = raw.decode('utf8', errors='ignore')
    raw += prefix.token_bytes[-1]
    token = raw.decode('utf8', errors='ignore')[len(previous):]
    if not token.isascii():
        token = normalize(token)
    value = response(token, history, position)
    history = (history + token)[-120:]
    return (doc, raw[-4:], history, position + 1), value

"""Detect source expressions, especially locative adverbs following 'from'.

Spatial boundaries and 'rest' give strong positive responses. Other place/time
adverbs give smaller ones; 'here/there' and 'what/whatever' are negative.
An intervening article weakens the response. Hyphenated phrases also count.
At document starts, use coarse grammatical and character-shape estimates:
lowercase nouns trend negative, caption subjects/navigation verbs positive.
Many word-specific responses at document starts are deliberately left out.
"""
import wordnet

NAVIGATION = {
    'show', 'browse', 'explore', 'search', 'view', 'find', 'read', 'watch'
}
HUMAN_SUBJECTS = {'person', 'someone', 'somebody', 'anyone', 'people'}


def initial_value(raw):
    if raw == '<|endoftext|>':
        return -6.55
    if raw == '\\t':
        return -3.55
    if raw == '\t':
        return -1.45
    if raw == '.\n':
        return -2.65
    word = raw.strip()
    if word.isascii() and word.isdigit():
        return -0.45
    if not (word.isascii() and word.isalpha() and len(word) > 1):
        return 0.0
    lower = word.lower()
    pos = wordnet.parts_of_speech(lower)
    if word.islower():
        if raw.startswith(' ') and 'noun' in pos and not word.endswith('s'):
            return -0.8
        return -0.15
    if not raw.startswith(' '):
        if lower in HUMAN_SUBJECTS:
            return 1.5
        if lower in NAVIGATION:
            return 1.4
    if 'verb' in pos and lower.endswith('ed'):
        return 0.4
    return 0.0


READS = ()

BOUNDARIES = {'above', 'below', 'within'}
DIRECTIONS = {'across', 'outside', 'behind'}
PLACE_TIME = {'around', 'now', 'today'}
OTHER_PLACES = {'abroad', 'elsewhere', 'wherever', 'over'}
SIDES = {'left', 'right'}
DEICTIC_QUESTIONS = {'here', 'there', 'what', 'whatever'}


def source_response(word):
    if word in BOUNDARIES or word == 'anywhere':
        return 6.3
    if word in DIRECTIONS:
        return 5.3
    if word in PLACE_TIME:
        return 3.7
    if word in OTHER_PLACES:
        return 2.4
    if word in SIDES:
        return 1.7
    if word in DEICTIC_QUESTIONS:
        return -1.5
    if word == 'home':
        return 2.3
    if word == 'rest':
        return 7.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    first = carry is None or carry[0] != doc
    if first:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    prev = previous.lower()
    value = initial_value(raw) if first else 0.0
    if prev == 'from':
        value = source_response(word)
        if word == 'home':
            if before_previous.lower() in {'work', 'works', 'working'}:
                value = 4.6
        if previous[:1].isupper():
            value *= 2.0 if value < 0 else 0.8
    elif before_previous.lower() == 'from' and prev in {'the', 'a', 'an'}:
        value = 0.22 * source_response(word)
    elif before_previous.lower() == 'from' and prev in {'-', ''}:
        factor = 0.75 if prev == '-' else 0.2
        value = factor * source_response(word)
    elif prev == 'bounded' and word in {'above', 'below'}:
        value = 8.0
    return (doc, raw.strip(), previous), value

"""Short un- beginnings, plus UN / United Nations.

Give a negative pulse to short, unfinished un- word beginnings. Recent
function words distinguish English and German prefixes from Romance
articles. Case, camel case, punctuation, and adjective cues modify its size.
Longer words, common four-letter words, and ordinary internal fragments
otherwise predict zero. Recognized United Nations names/initials give a
separate negative pulse. An initial 'Title:' header's colon gives a positive
pulse. Keep 256 text characters and reset this tail at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ENGLISH = set('the and of to is for that with it be are an this was not '
              'have from but you which can has will been should would there '
              'we they its their our your than these such'.split())
GERMAN = set('der die das den dem des ein eine und uns ist mit zu von auf '
             'nicht sich auch im für als'.split())
ROMANCE = set('de la el que en y los las una por con para del le les des du et '
              'une est dans pour qui avec sur pas ce au che il lo gli della '
              'delle dei di si non per come sono alla anche al nel nella più '
              'su mi ci essere ha se uno un din cu este și sau care pe mai o'.split())
ADJECTIVE_CUES = set('an very so too more most quite rather extremely deeply '
                     'utterly completely'.split())


@lru_cache(maxsize=4096)
def common_word(word):
    return zipf_frequency(word, 'en') >= 3.0


def response(history, token):
    if token == ':' and re.search(r'(?:^|<\|endoftext\|>)Title\Z', history):
        return 8.8
    if token.strip() == 'Nations' and re.search(r'\bUnited\s*\Z', history):
        return -14.7
    if token in ('.N', '-N') and re.search(r'\bU\Z', history):
        return -10.54 if token == '.N' else -8.0
    if (history + token).endswith(('联合国', '聯合國', '国連')):
        return -8.16
    if token == '엔' and history.endswith('유'):
        return -8.16
    if re.search(r'(?<![A-Za-z])UN\Z', token):
        return -5.54 if token[:1].isspace() else -3.66

    part = re.search(r'[A-Za-z]+\Z', token)
    if not part:
        return 0.0
    old = re.search(r'[A-Za-z]+\Z', history)
    joined = part.start() == 0 and old is not None
    camel = joined and part.group().startswith('Un')
    word = part.group()
    if joined and not camel:
        word = old.group() + word
    w = word.lower()
    # Common four-letter words (e.g. unit, undo) are not unfinished prefixes.
    if not w.startswith('un') or len(w) > 4:
        return 0.0
    if len(w) == 4 and common_word(w):
        return 0.0
    if word.isupper() and len(w) > 2:
        return -7.0  # Extended UN initialisms, including split U + NT.
    if joined and old.group().lower() == 'u':
        return -5.5
    if joined and not camel and old.group().lower().startswith('un'):
        if len(old.group()) == 2 and not w.startswith('uni'):
            return -4.22
        return 0.0
    if camel:
        return -2.84
    if part.start() and not token[:1].isspace():
        code = any(c in '._/([{' for c in token[:part.start()])
        return -2.65 if code else -1.77
    if len(w) == 3 and w[2] in 'aeio':
        return 0.0

    words = re.findall(r'[^\W\d_]+', history.lower())
    en = sum(x in ENGLISH for x in words)
    de = sum(x in GERMAN for x in words)
    romance = sum(x in ROMANCE for x in words)
    if w in ('und', 'uns') and de > 0 and de >= en:
        return 0.0  # German conjunction/pronoun, not a negative prefix.
    if word[0].isupper():
        return -3.03 if len(w) == 2 else -3.15
    if en > max(de, romance):
        cue = bool(words and words[-1] in ADJECTIVE_CUES)
        return -6.39 - (1.13 if cue else 0.0)
    if de > romance:
        return -3.54
    if romance > en:
        return -0.86
    return -4.05 if en + de + romance == 0 else -4.63


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(history, token)
    return (doc, (history + token)[-256:]), float(value)

"""Recognize markup delimiters, rather than the words they surround.

Citations, documentation links, entities, nested brackets and JSON closings
give positive pulses. TeX reference arguments, TeX group openings, and the
partial UTF-8 prefix of a flag symbol give negative pulses. Ordinary text
is zero except for a small document-start baseline. Short text and byte tails
are cleared at document boundaries.
"""
import re

READS = ()

def markup_pulse(s, previous, tail, first, byte_tail=b''):
    """Estimate the signed pulse for the current syntactic event."""
    t = s.strip()
    if byte_tail.endswith(b'\xf0\x9f\x87'):
        return -2.35
    if first:
        if s.startswith('<|'):
            return -0.14
        if any(c.isalpha() for c in s):
            return -0.14 if s[0].isspace() else -0.26
        return -0.15
    if (t == ':' and previous == 'Title' and
            (tail == 'Title' or tail.endswith('<|endoftext|>Title'))):
        return -3.3
    # Link and documentation names after their opening markers.
    if t in ('link', 'linkplain') and tail.endswith('{@'):
        return 9.26
    if t == 'link' and tail.endswith(('[', '@')):
        return 4.39
    if t in ('http', 'https', 'file') and tail.endswith('['):
        return 2.25
    if t == 'cite' and tail.endswith('\\'):
        return 1.04
    if t == 'ref' and tail.endswith('\\'):
        return 0.75
    if t == 'see' and tail.endswith('@'):
        return 2.39
    if t == 'ref' and tail.endswith('@'):
        return 0.66
    if t == 'var' and tail.endswith('@'):
        return 1.39
    if t == '="' and tail.endswith('cref'):
        return 4.04
    if t == '#' and tail.endswith('{'):
        return 0.6
    # Nested bracket punctuation, with a prose/code distinction.
    if t.startswith('[['):
        code = bool(re.search(r'(?:[=(,]|Callable)\s*$', tail))
        return 0.86 if code else 2.37
    if t.startswith(']]'):
        if tail.endswith('\\'):
            return -1.82
        if '[[' in tail:
            name = tail.rsplit('[[', 1)[-1]
            if re.fullmatch(r'[\w ,|()←–-]*[A-Za-z][\w ,|()←–-]*', name):
                return 2.7
            return 0.72
        return 0.4
    if t.startswith('))'):
        return 0.18
    if (t == '[' and tail.endswith('\\')) or t == '\\[':
        return -0.44
    if len(t) >= 2 and set(t) == {'·'}:
        return -0.45
    if previous.strip() == '&#' and t.isdigit():
        return 0.43
    if s.endswith('}}\n'):
        return 0.92 if tail.endswith('\\n') else 0.58
    if t == 'permalink' and tail.endswith('[#'):
        return 0.62
    # PLoS ONE citation keys use the journal's identifier prefix.
    if t == 'pone' and tail.endswith('[@'):
        return 3.86
    if t in ('[@', '[@@'):
        if re.search(r'\$\{[A-Za-z_][A-Za-z_0-9]*$', tail):
