READS = ()

FULL_PREFIXES = {
    "intra", "ultra", "extra", "infra", "supra", "ekstra",
    "интра", "ультра", "экстра", "инфра", "супра",
}
STEMS = {"intr", "ultr", "extr", "infr", "supr", "интр", "ультр", "экстр", "инфр", "супр"}

FULL_VALUE = 5.0   # whole-word prefix token
STEM_VALUE = 3.0   # stem token opening such a word
PIECE_VALUE = 3.9  # short follow-on piece after a stem


def starts_word(text):
    return text[:1].isspace() or (text != "" and not text[0].isalnum())


def word_before(prefix, t):
    """The word-so-far in front of token t (lowercase), or '' if token t starts a new word."""
    if starts_word(prefix.token_strings[t]):
        return ""
    parts = []
    j = t - 1
    while j >= 0 and prefix.document_ids[j] == prefix.document_ids[t]:
        parts.append(prefix.token_strings[j])
        if starts_word(prefix.token_strings[j]):
            break
        j -= 1
