    t = prefix.position
    piece = prefix.token_strings[t].strip().lower()
    if piece in FULL_PREFIXES:
        return carry, FULL_VALUE
    if piece in STEMS:
        return carry, STEM_VALUE
    if len(piece) <= 4 and word_before(prefix, t) in STEMS:
        return carry, PIECE_VALUE
    return carry, 0.0

