    elif onset == 'n':
        answer = 0.2
    elif onset == 'r':
        answer = -0.4
    elif gap in ('a', 'o'):
        answer = -3.0 if y else -1.8
    elif onset == 'l':
        answer = -1.0
    else:
        answer = -0.2
    if r_old and onset == 't' and gap == 'o':
        return 1.6
    return answer * (0.55 if r_old else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        old = ''
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
    else:
        _, old, decoder = carry
    token = decoder.decode(prefix.token_bytes[-1])
    prediction = value(old, token, first)
    old = (old + anyascii(token).lower())[-24:]
    return (doc, old, decoder), float(prediction)

"""A typographic approximation, not a word-by-word activation table.

Document openings are usually negative, increasingly so for long tokens.
Elsewhere the signal is small: digits, quotes and certain symbols lower it.
A blank line after </think> gets a distinct positive response.  The previous
token's formatting supplies a small correction. Fine lexical variation
is deliberately left out.
"""
READS = ()

# Groups of familiar punctuation, with small additive corrections.
PUNCTUATION = (
    ("'’‘\"“”", -0.009),  # quotation marks
    ('`', -0.018),         # code quotation
    ('.,;()[]{}', 0.014),  # prose/code separators
    ('/\\', -0.012),       # slashes
    ('@%', -0.055),        # address/percentage signs
    ('$¥￥', -0.035),       # currency signs
    ('!', -0.038),
    ('?', 0.018),
    ('，。！？：；、—', 0.032),
)


def ordinary(token):
    t = token.strip()
    if '\x00' in token:
        return -0.115
    if token == '\r':
        return 0.12
    if '\xa0' in token:
        return -0.08
    if t.isdecimal():
        digit = int(t) if len(t) == 1 and t.isascii() else 4.5
        return 0.003 - 0.025 * digit / 9
    if t.isalpha():
        value = 0.005 - 0.009 * (len(t) == 1)
    else:
        value = -0.007 if not t else -0.01
    for marks, adjustment in PUNCTUATION:
        if any(c in marks for c in t):
            value += adjustment
    return value


def opening(token):
    t = token.strip()
    if token == '<|im_start|>':
        return -0.474
    if t.isdecimal():
        return -0.34
    if not t:
        return -0.24
    if len(t) == 1 and t.isalpha():
        return -0.02
    value = -0.13 - 0.055 * min(len(t), 8)
    value += 0.06 * token.startswith(' ')
    value += 0.07 * (t.isalpha() and t.islower())
    if not t.isascii():
        value -= 0.13
    if t[0] in '#/':
        value -= 0.24
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token), opening(token)
    previous = carry[1]
    value = ordinary(token)
    if token == '\n\n' and previous in ('<think>', '</think>'):
        value = 0.185 if previous == '</think>' else 0.075
    else:
        if previous.strip().isdecimal():
            value -= 0.015
        if '\xa0' in previous:
            value -= 0.05
        if previous == '\r':
            value += 0.13
        if '\x00' in previous and '\x00' not in token:
            value -= 0.12
        if previous == '<|im_end|>':
            value += 0.06
        if previous == '</tool_call>':
            value -= 0.06
    if token == '<|im_end|>':
        value += 0.06
    if token == '</tool_call>':
        value = -0.145
    return (doc, token), value

programs.haiku:
"""Layer-1 MLP down-projection component 5269, as two readable rules.

Almost everywhere in a document this component is nearly silent: its activation is small
(std about 0.05) and has no simple pattern, so the program predicts 0 there.

Rule 1, the first token of a document (position 0 of a row, or the token right after a
<|endoftext|> / <|im_end|> boundary inside a packed row). The first token attends only to
itself, so its value is set by which token it is, and it is almost always negative:
  - special markers such as <|im_start|>: about -0.5;
  - a run of whitespace (indentation, tabs, newlines): about -0.5; a lone space: about +0.06;
  - a word or punctuation mark: about -0.25, a word with a leading space a bit less.

Rule 2, the empty reasoning block of a chat reply: the "\n\n" right after "</think>".
This is the one place it reliably fires (causal importance near 1), at about +0.19.
"""

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings[-1]
    if t > 0 and s == "\n\n" and prefix.token_strings[-2] == "</think>":
        return carry, 0.19
    if t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return carry, 0.0
    if s.startswith("<|"):
        value = -0.5
    elif s.strip() == "":
        value = 0.06 if s == " " else -0.5
    elif s[:1] == " " and s[1:2].isalpha():
        value = -0.24
    else:
        value = -0.27
    return carry, value

programs.sol:
"""Approximate an O-ending/zero signal, not a phonetic classifier.

O-final spellings are strongest; os/oe endings and transliterated endings
also contribute. Length, script, case, punctuation and a few common
English words adjust the level. Numeric zeros weaken in decimals and
zero runs; some common 'to' phrases also weaken. Document starts get a
negative offset. Partial UTF-8 tokens get a small fallback; NUL is treated
as a zero-like character. These are fitted tendencies, not exact rules
for the original component.
"""
from functools import lru_cache
import re
import unicodedata
import regex
from anyascii import anyascii
import wordnet

READS = ()


@lru_cache(maxsize=20000)
def spelling(s):
    t = s.strip()
    a = anyascii(t).lower()
    v = -0.004
    if a.endswith('o'):
        v += 1.00
        if len(a) >= 5:
            v -= 0.24
        if t and not t[0].isalpha():
            v -= 0.18
        if t.isupper() and len(t) > 1:
            v += 0.26
        name = unicodedata.name(t[-1], '') if t else ''
        if 'LATIN' in name and ord(t[-1]) > 127:
            v -= 0.30
        elif regex.search(r'\p{Script=Cyrillic}', t):
            v -= 0.28
        elif regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', t):
            v -= 0.55
        elif regex.search(r'\p{Script=Han}', t):
            v -= 0.67
        elif not t.isascii() and not regex.search(r'\p{Script=Greek}', t):
            v -= 0.40
        # Omicron looks like o; omega is a different Greek letter.
        if 'OMEGA' in name:
            v -= 0.90
    elif a.endswith('os'):
        v += 0.53
    elif a.endswith('oe'):
        v += 0.50
    elif 'o' in a:
        v += 0.03
    if a == '0':
        v += 0.83
    if '\ufffd' in t:
        v += 0.23
    if len(a) > 7 and t.isalpha():
        v -= 0.03
    if a in ('two', 'too'):
        v -= 0.97
    if a == 'who':
        v -= 0.81
    if a == 'also':
        v -= 0.61
    if s[:1].isspace() and t.islower() and a in ('do', 'go'):
        v -= 0.46
    if t in ('did', 'does'):
        v += 0.66
    if t == '\x00':  # ASCII NUL is the zero-valued character.
        v += 1.70
    return t.lower(), a, v


@lru_cache(maxsize=4000)
def verb_bases(word):
    return set(wordnet.base_forms(word)) | {word}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, tail = ('', '') if start else carry[1:]
    s = prefix.token_strings[-1]
    t, roman, v = spelling(s)
    if t == '0':
        match = re.search(r'[\d.]+$', tail)
        number = match[0] if match else ''
        decimal = '.' in number
        if number == '2':
            v -= 0.64
        if previous.isdigit() and previous != '0':
            v += 0.14
        if len(number) >= 2 and number[-1:] != '0' and not decimal:
            v += 0.24
        if decimal:
            v -= 0.16
            if re.fullmatch(r'0+\.[0-9]*', number):
                v -= 0.58
        v -= 0.063 * (len(number) - len(number.rstrip('0')))
        if number and not number.strip('0'):
            v -= 0.59
        if number == '20':
            v += 0.47
    if t == 'to':
        if previous in ('according', 'addition'):
            v -= 0.88
        bases = verb_bases(previous)
        if bases & {'continue', 'ready'}:
            v -= 1.24
        if bases & {'try', 'help'}:
            v -= 0.45
    if t.endswith('o') and previous.endswith('o'):
        v -= 0.23
    if start:
        v -= 0.85
    return (doc, t, (tail + s)[-24:]), float(v)

programs.haiku:
"""Component layers.1.mlp.down_proj:5271 (Qwen3-1.7B, layer 1 MLP down-projection).

What it responds to, in plain terms: the word "to" and other short tokens whose
spelling ends in the letter o, plus the digit 0.

The component's activation at a position depends only on the token there, so the
program looks only at the newest token (no memory is needed):

- the digit "0" -> about 1.0, but weaker (0.45) when it follows "2" or "." (as in
  the "20" that starts a number, or a decimal point);
- a token whose letters end in an o-like letter (o, ó, ö, ø, ο Greek, о Cyrillic,
  and so on) -> 1.0, e.g. " to", " into", " so", " no", "ro", "то". Words that
  contain "w" or "oo" are skipped (two, who, too), and do/go/also are weaker (0.4);
- anything else -> 0.

Why: "to" alone is the largest single source of this component's variance, and the
digit 0 is the second largest; the other o-ending tokens follow the same pattern. Long
words that merely contain an o (of, for, column, attention) stay at 0.
"""

READS: tuple[str, ...] = ()  # reads no other component

O_LIKE = set("oóòôöøōőοо")  # Latin o with accents, Greek omicron, Cyrillic o
WEAK = {"do", "go", "also"}


def _letters(text):
    return "".join(c for c in text.lower() if c.isalpha())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = _letters(token)
    if token == "0":
        before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
        value = 0.45 if before in ("2", ".") else 1.0
    elif word and word[-1] in O_LIKE and "w" not in word and "oo" not in word:
        value = 0.4 if word in WEAK else 1.0
    else:
        value = 0.0
    return carry, float(value)

"""Data-type, null and default words in code and schemas.

What it is: this component writes a signed amount into the residual stream. The amount is
large on the words that name a kind of value in code or in a schema:

- the type name `string` (and `str`, `String`), which is the strongest;
- other type names: `bool`, `array`, `object`, `int`, `float`, `void`, `Optional`, ...;
- null-like values: `null`, `NULL`, `nil`, `None`, `undefined`;
- the words that mark a field as optional, required or defaulted: `default`, `DEFAULT`,
  `optional`, `required`, `description`;
- weaker: `value`, `values`, `arguments`, `path`, `type`, `self`;
- slightly negative: shell and web words such as `command`, `package`, `github`, `www`.

It is raised by about half when the word follows a colon, quote, brace or parenthesis
(`name: string`, `"type": "string"`, `{ type: 'string' }`), or when a schema word such as
`type`, `properties`, `parameters` or `Joi` comes a few tokens before it.

The program looks only at the current token and the few tokens before it. It keeps no state.
"""

READS = ()

STRING_TYPE = {"string", "str", "String", "<String", "(string", "_string", "_str"}
OTHER_TYPES = {
    "bool", "boolean", "Boolean", "int", "integer", "Integer", "INTEGER", "uint", "Int",
    "float", "double", "Double", "char", "byte", "number", "Number", "array", "Array",
    "object", "Object", "void", "varchar", "VARCHAR", "struct", "List", "Option",
    "Optional", "Required", "Nullable", "true", "false", "True", "False",
}
NULL_WORDS = {"null", "NULL", "nil", "None", "undefined", "Null"}
DEFAULT_WORDS = {"default", "Default", "DEFAULT", "optional", "Optional", "required",
                 "Required", "description", "Description"}
WEAK_WORDS = {"value", "values", "Value", "arguments", "argument", "path", "parameter",
              "self", "type", "Type", "keys", "properties", "schema"}
NEGATIVE_WORDS = {"command", "commands", "package", "github", "www", "Download", "permalink",
                  "repo", "deploy", ".io", "Tags"}
VALUE_OPENERS = {":", "?:", '"', "'", "`", "{", "(", "Joi", "="}
SCHEMA_WORDS = {"type", "schema", "properties", "parameters", "Joi", "typing", "struct",
                "arguments", "interface", "param"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lstrip(".").strip()
    if word in STRING_TYPE:
        value = 1.3
    elif word in DEFAULT_WORDS:
        value = 1.1
    elif word in NULL_WORDS:
        value = 0.9
    elif word in OTHER_TYPES:
        value = 0.4
    elif word in WEAK_WORDS:
        value = 0.4
    elif word in NEGATIVE_WORDS:
        return carry, -0.3
    else:
        return carry, 0.0
    if len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip() in VALUE_OPENERS:
        value *= 1.5
    before = {s.strip().strip('"') for s in prefix.token_strings[-7:-1]}
    if before & SCHEMA_WORDS:
        value *= 1.5
    return carry, value

programs.sol:
"""A lexical subject-pronoun signal, attenuated in English object/question contexts.

English pronouns have a negative response, weakened after an auxiliary
('are you') or, for you/it, an object-taking word ('for you', 'use it').
A small rolling language cue distinguishes French 'on' from English 'on',
and German 'man' from English 'man'.  Other entries are subject pronouns,
not arbitrary vocabulary. Strengths are coarse training averages; this
lexical approximation ignores finer syntactic and contextual distinctions.
"""
import re
import wordnet

READS = ()
HAN_PRONOUNS = frozenset('我你他她您')

ENGLISH = {
    'I': -1.65, 'i': -0.25, 'you': -1.85, 'he': -1.78,
    'she': -2.02, 'we': -1.65, 'they': -1.77, 'it': -1.0,
    'there': -0.85, 'this': -0.22, 'that': -0.06,
    'these': -0.27, 'those': -0.06,
}
CAPITALIZED = {
    'You': -1.9, 'He': -1.5, 'She': -1.65, 'We': -1.3,
    'They': -1.65, 'It': -0.92, 'There': -0.78,
    'This': -0.49, 'That': -0.55, 'These': -0.61, 'Those': -0.3,
}
AUXILIARIES = set('''am is are was were do does did have has had can could
    shall should will would must may might ought'''.split())
PREPOSITIONS = set('''to for of with at by from in on about against between into
    through without behind beside near upon around over under than'''.split())
OBJECT_VERBS = set('''use make take put keep give tell ask thank help let
    get call love hate like invite bring leave watch hear send show save
    protect allow teach need want try enjoy understand follow'''.split())
ROMAN_LABELS = set('''war annex appendix volume vol part section chapter
    stage phase type class act figure table'''.split())
LANGUAGE_WORDS = {
    'en': set('the and of a to is in on at for that with was as not have you it'.split()),
    'de': set('''der die das und ist mit sich nicht ein eine zu auf für
        von den dem des dass kann wird im aber wenn wie'''.split()),
    'fr': set('''le la les de des du et est une un que qui dans pour
        ne pas au ce en avec sur merci bonjour'''.split()),
    'it': set('di che e il la le un una in per del della non con sono'.split()),
    'es': set('el los las de del en que por para una un es con se su sus más pero'.split()),
    'nl': set('het een van niet voor zijn op als de en dat met deze'.split()),
    'scandinavian': set('''och og att det är er som på av inte ikke med
        för for till den at kan har å'''.split()),
}
DISTINCTIVE = {
    lang: markers - set().union(*(other for name, other
                                  in LANGUAGE_WORDS.items() if name != lang))
    for lang, markers in LANGUAGE_WORDS.items()
}
OTHER_PRONOUNS = {
    'nous': -1.15, 'vous': -1.15, 'ils': -3.4,
    'elles': -3.9, 'sie': -1.1, 'wir': -2.8, 'ihr': -1.3,
    'я': -0.83, 'ты': -0.75, 'он': -1.25, 'она': -1.25,
    'мы': -0.9, 'вы': -0.76, 'они': -1.08,
    'yo': -0.8, 'usted': -0.65, 'você': -0.7,
    'bạn': -0.7, 'tôi': -0.5, 'se': -0.55,
}
# Shared spellings are interpreted using the surrounding language.
LANGUAGE_PRONOUNS = {
    'de': {'man': -5.0, 'ich': -3.8, 'er': -2.3, 'Er': -1.2, 'du': -4.1},
    'fr': {'on': -6.7, 'je': -4.5, 'il': -3.4, 'tu': -4.1,
           'j': -3.5, 'c': -2.8, 'elle': -3.2},
    'scandinavian': {'man': -5.0, 'du': -4.1, 'jag': -6.5, 'vi': -5.5,
              'hon': -6.0, 'jeg': -7.0, 'han': -4.5, 'hun': -4.5},
    'nl': {'ik': -4.0, 'ze': -3.5},
}
AMBIGUOUS = {w for group in LANGUAGE_PRONOUNS.values() for w in group}
WORD = re.compile(r"[^\W\d_]+(?:['’][^\W\d_]+)?|[^\w\s]")


def predict(token, tail):
    word = token.strip()
    if word.startswith(('-', '_', '<', '$')):
        return 0.0
    if word and word[0] in '我你他她它您':
        if word in HAN_PRONOUNS:
            return -0.95
        if word == '它':
            return -0.58
        if word[1:] in ('们', '們'):
            return -0.8
        if word[1:] in ('会', '将', '能') or word[1:] == '们将':
            return -0.65
        return 0.0
    match = re.fullmatch(r"[\W_]*([^\W\d_]+)[\W_]*", word)
    if not match:
        return 0.0
    word = match[1]
    lower = word.lower()
    if word not in ENGLISH and word not in CAPITALIZED:
        if lower not in OTHER_PRONOUNS and lower not in AMBIGUOUS:
            return 0.0
    if token[0].isalpha() and tail and (tail[-1].isalnum() or tail[-1] == '_'):
        return 0.0  # continuation of an earlier word
    parts = WORD.findall(tail)
    previous = parts[-1].lower() if parts else ''
    if word in ENGLISH or word in CAPITALIZED:
        value = ENGLISH.get(word, CAPITALIZED.get(word, 0.0))
        auxiliary = previous.replace('’', "'")
        if auxiliary.endswith("n't"):
            auxiliary = auxiliary[:-3]
            auxiliary = {'ca': 'can', 'wo': 'will', 'sha': 'shall'}.get(auxiliary, auxiliary)
        if auxiliary in AUXILIARIES:
            if lower == 'you':
                be_or_have = auxiliary in {
                    'am', 'is', 'are', 'was', 'were', 'have', 'has', 'had'}
                value = -0.15 if be_or_have else -0.85
            else:
                value = {'i': -0.3, 'he': -0.8, 'she': -0.8,
                         'we': 0.05, 'they': -0.3, 'it': 0.15}.get(lower, value)
                if lower == 'it' and auxiliary in ('is', 'are', 'was', 'were'):
                    value = 0.5
        elif lower in ('you', 'it'):
            bases = set(wordnet.base_forms(previous)) | {previous}
            if previous in PREPOSITIONS:
                value = -0.45 if lower == 'you' else 0.15
            elif bases & OBJECT_VERBS:
                value = -0.85 if lower == 'you' else -0.02
            elif lower == 'it' and bases & {
                    'think', 'know', 'believe', 'suppose', 'guess'}:
                value = -0.5
        if word == 'I' and previous in ('.', '?', '!', ':', '(', '"', '“', '”'):
            value = -1.3
        clause_start = previous in {',', ';', 'and', 'but', 'if', 'when', 'as'}
        if lower in ('this', 'that', 'these', 'those') and clause_start:
            value = {'this': -0.5, 'that': -0.5, 'these': -0.6, 'those': -0.3}[lower]
        if word == 'I' and previous in ROMAN_LABELS:
            value = 0.1
        if not tail and word in ('I', 'i', 'you', 'he', 'she', 'we', 'they', 'it'):
            value = -0.65 if word == 'I' else 0.35
        return value
    if word.isupper() and lower not in ('я', 'ты', 'вы', 'мы', 'j', 'c'):
        return 0.0
    if lower in OTHER_PRONOUNS:
        return OTHER_PRONOUNS[lower]
    # A new document/chat turn can change language even inside a packed row.
    context = tail.rsplit('<|endoftext|>', 1)[-1]
    context = context.rsplit('<|im_start|>', 1)[-1]
    words = re.findall(r'\b[^\W\d_]+\b', context.lower())
    scores = {lang: sum(w in markers for w in words)
              for lang, markers in LANGUAGE_WORDS.items()}
    lang = max(scores, key=scores.get)
    if scores[lang] < 3 and not any(w in DISTINCTIVE[lang] for w in words):
        lang = ''
    if lower in ('on', 'il') and token.lstrip().startswith(("'", '’')):
        return LANGUAGE_PRONOUNS['fr'][lower]
    if lower == 'on' and scores['fr'] < scores['en'] + 3:
        return 0.05
    fallback = {'on': 0.05, 'man': 0.05, 'ich': -0.6,
                'er': 0.15, 'je': -0.25}.get(lower, 0.0)
    readings = LANGUAGE_PRONOUNS.get(lang, {})
    return readings.get(word, readings.get(lower, fallback))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, tail)
    return (doc, (tail + token)[-512:]), float(value)

"""A small opening-token and web-address detector.

The ordinary response is nearly zero. Document openings get a negative
baseline, except for a function declaration or a literal backslash escape.
The .com suffix is positive after the AWS documentation host or the example
placeholder host. Opening filename/issue tags give a negative pulse.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, tail = 0, ''
    else:
        _, position, tail = carry
    token = prefix.token_strings[-1]
    value = 0.001
    if position == 0:
        value = -0.21
        if token == 'function':
            value = 3.13
        elif token == r'\n':
            value = 1.74
        elif token == r'\xc':
            value = 1.94
    elif position == 1 and tail == '<':
        if token == 'issue':
            value = -2.17
        elif token == 'filename':
            value = -2.01
    if token == '.com':
        value = -0.07
        if tail.endswith('docs.aws.amazon'):
            value = 1.28
        elif tail.endswith('example'):
            value = 0.65 if '@' in tail[-20:] else 0.34
    return (doc, position + 1, (tail + token)[-80:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:5275: a nearly silent direction of layer 1's MLP output.

Its activation is about 0 almost everywhere (typical size 0.04) and has no readable
pattern in the ordinary text, so this program predicts only what can be read:

1. Document openings. A packed row restarts at each document; the first token has
   nothing before it, so the token alone sets the value. Ordinary openers are negative:
   mid-sentence fragments (lowercase words, words with a leading space, punctuation)
   about -0.25, capitalised words about -0.15, digits about -0.05. Some code and escape
   openers spike: 'function' 3.1, 'def' and '#ifndef' 1.1, a literal backslash-n 1.7.
2. Domain names. The '.com' closing 'docs.aws.amazon' gives 1.3, and the '.com' closing
   'example' (an e-mail address) 0.6. Every other position predicts 0.
"""

READS = ()

DOC_OPENERS = {"function": 3.1, "def": 1.1, "#ifndef": 1.1, "\\n": 1.7}
DOMAIN_ENDINGS = {"amazon": 1.3, "example": 0.6}


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if starts_document:
        if token in DOC_OPENERS:
            return None, DOC_OPENERS[token]
        word = token.strip()
        if word[:1].isdigit():
            return None, -0.05
        if word[:1].isupper():
            return None, -0.15
        return None, -0.25
    if token == ".com":
        previous = prefix.token_strings[t - 1]
        for ending, value in DOMAIN_ENDINGS.items():
            if previous.endswith(ending):
                return None, value
    return None, 0.0

programs.sol:
"""A local spelling-and-code-context approximation.

Positive: short r/a/hard-consonant fragments, especially across a token
boundary, with a separate boost for the chemical carboxyl prefix.
Negative: R/C introducing code vocabulary, language labels, Unix permissions
and package/local paths. Romanization shares the spelling rules across scripts.
Only the preceding token is retained; documents reset this state.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = {'c', 'r', 'go', 'java', 'ruby', 'python'}
CODE_WORDS = {
    'code', 'program', 'programming', 'function', 'implementation',
    'definition', 'language', 'script', 'software', 'statistical',
    'statistics', 'studio', 'package', 'library', 'cpp',
}


@lru_cache(maxsize=40000)
def roman(text):
    return anyascii(text).lower()


def matches(pattern, text):
    return re.fullmatch(pattern, text) is not None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, last_raw = ('', b'')
    if carry is not None and carry[0] == doc:
        previous, last_raw = carry[1:]
    current = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    p, c = roman(previous), roman(current)
    word = c.strip()
    after_r = p.endswith('r')
    continuation = bool(c) and c[0].isalpha()
    value = -0.056 if not previous else 0.0

    # Syllable-like spellings, not an attempted phonetic transcription.
    if matches(r'[aeou]?ra[bpcgkqxh]{1,2}[aeiou]?', word):
        if not current.isascii() or zipf_frequency(word, 'en') < 3:
            value += 1.23
    if not current.isascii() and matches(r'r[bpkqg]', c):
        value += 1.15
    if matches(r'a[bpcgkqxh]{1,2}[aeiou]?', c):
        if after_r:
            value += 0.74 + 0.72 * (len(c) == 2)
            if p.endswith('ar'):
                value += 0.62 + 0.46 * (len(c) == 2)
        elif 'r' in p[-3:]:
            value += 0.08
    if after_r and matches(r'[eou][bpcgkqxh]{1,2}[aeiou]?', c):
        value += 0.11
    if p.endswith('ra') and continuation and len(c) <= 4:
        if c[0] in 'bpcgkqxh':
            value += 0.43
    if after_r and matches(r'[bpcgk][ao][bpcgkx]{1,2}h?', c):
        value += 1.12
    if p.endswith('car') and c == 'box':
        value += 2.07
    if '\ufffd' in previous + current:
        joined = (last_raw + raw).decode('utf-8', errors='replace')
        if re.search(r'r[aeou]?[bpcgkqx]', roman(joined)):
            value += 0.95

    # Letter-name acronyms versus programming-language uses of R and C.
    name = previous.strip()
    if name.endswith('R') and name.isupper() and len(name) < 4:
        if current.isupper() and len(current) == 2:
            value += 0.19
    technical = word in CODE_WORDS or current in {'语言', '語言', '语言中'}
    language = p.strip()
    if name == 'R':
        value -= 0.09 * (not continuation)
        value -= 0.33 * (current.startswith(' ') and word.isalpha())
    if technical:
        if language == 'r':
            value -= 6.32
        elif language == 'c':
            value -= 4.11
        elif language in LANGUAGES:
            value -= 1.04 + 2.64 * (language == 'go')
    if language in LANGUAGES:
        if c.startswith(('\n', '\r')):
            value -= 0.25
        if word == 'interpreter':
            value -= 0.41
    if language in {'r', 'c'} and c.startswith(('++', '#')) and '\n' in c:
        value -= 1.33
    if language == 'go' and word in {'test', 'run', 'build', 'install'}:
        value -= 0.90

    # Unix permission fields and conventional installation/package paths.
    if language in {'r', '-r'} and matches(r'[-rwx]{2,}', c):
        value -= 1.21 + 2.04 * (c == '--')
    if p == 'usr' and c == '/local':
        value -= 1.07
    if c in {'pkg', '/pkg', ' pkg'}:
        value -= 0.55
    if c == 'usr' and p.endswith('/'):
        value -= 0.29
    return (doc, current, raw), float(value)

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:5279.

The component is silent inside a document and switches on at the first token of each
document (the first token of a row, or the first token after <|endoftext|>), where the
model has no earlier text to lean on. There its value is set by what that token looks
like out of context:
  - C/C++ type names (int, void, char, bool, ...) and a few code tokens: strongly positive
  - '#' and '//' comment openers: moderately positive
  - ordinary word-like and non-Latin tokens: weakly positive
  - digits and bare numbers: about zero
  - code import/include keywords (import, using, #include, ...): negative
Everywhere else the prediction is 0.
"""
import re

READS = ()

C_TYPES = {"int", "uint", "void", "bool", "char", "float", "double", "string", "byte",
           "unsigned", "wchar", "wstring", "UINT", "DWORD", "BOOL", "GLuint", "HRESULT"}
CODE_KEYWORDS = {"import", "using", "#include", "package", "export", "require", "include", "use"}


def _value(token):
    """The activation at a document's first token, from the token's own text."""
    t = token.strip()
    if t in C_TYPES:
        return 1.5
    if t in CODE_KEYWORDS:
        return -0.4
    if t in ("#", "//"):
        return 0.5
    if not t:
        return 0.05
    if re.fullmatch(r"[0-9]+", t):
        return -0.04
    if re.fullmatch(r"[^A-Za-z0-9\s]+", t) and not any(ord(c) > 0x2E80 for c in t):
        return 0.11
    if any(ord(c) > 0x2E80 for c in t):
        return 0.2
    if token[:1] == " ":
        return 0.14
    return 0.07


def step(carry, prefix, upstream):
    """Predict the component at the newest token of the prefix."""
    starts_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    return None, float(_value(prefix.token_strings[-1]))

programs.sol:
"""A lexical possessive-determiner signal, with formatting side responses.

English first/third-person forms are positive; 'your' is weak. Capitalization
usually weakens them; preceding grammatical context changes their strength.
Ignore interior word fragments, but detect a possessive completed across tokens.
French/Spanish forms require nearby language cues. Selected standalone pronouns
are negative. Escaped backslashes are positive, TeX line breaks negative.
Blank lines after reasoning tags, form feeds, and NUL padding are separate cases.
Coefficients approximate observed training activations, not a full syntax parser.
"""
import re
import wordnet
from functools import lru_cache

READS = ()
ENGLISH = dict(my=.44, our=.56, his=.28, her=.49, its=.54,
               their=.49, your=0., thy=1.1)
FRENCH = dict(mon=.95, ma=.5, mes=.3, ton=.5, ta=.5, tes=.4,
              son=1.05, sa=.9, ses=.5, notre=.85, nos=.6,
              votre=.82, vos=.55, leur=1.05, leurs=.8)
SPANISH = dict(mi=1., mis=.7, tu=1.1, tus=.75, su=1.1, sus=.8,
               nuestro=.45, nuestra=.6, nuestros=.3, nuestras=.3)
ROMANCE_CUES = set('de du des le les la et une pour dans avec au aux '
                   'est qui à el los las del una para por con que en'.split())
ENGLISH_CUES = set('the and of to with from for is are that this'.split())
INDEPENDENT = set('he him you me yourself yourselves myself himself own'.split())
TEX = re.compile(r'\\(?:frac|sqrt|begin|end|left|right|text|mathrm|mathbf|'
                 r'color|vec|hat|tilde|lim|sum|overline|hfill|Pi|Tr)(?![A-Za-z])')
SLASHES = re.compile(r'\\{2,}')
POSSESSIVE_WORD = re.compile(r'(?<!\w)(' + '|'.join(ENGLISH) + r')$')
ENDINGS = {w[i:] for w in ENGLISH for i in range(1, len(w))}


@lru_cache(maxsize=2048)
def verb(word):
    return (word not in {'be', 'is', 'are', 'was', 'were', 'am', 'been'}
            and 'verb' in wordnet.parts_of_speech(word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.)
    _, context, previous, romance = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    boundary = bool(context) and not context[-1].isalnum()
    value = -.004
    if lower in ENGLISH:
        value = ENGLISH[lower]
        if word != lower:
            value *= 1. if lower in {'our', 'thy'} else .65
        elif spaced:
            if (previous in {'and', 'or'}
                    and lower in {'his', 'her', 'its', 'their'}):
                value += .28
            elif verb(previous):
                value += .13
            elif previous in {'all', 'out', 'down', 'off'}:
                value += .25
            elif previous == 'if':
                value -= .19
        if not spaced:
            value = value * .65 if boundary else 0.
        if word.isupper() and len(word) > 1:
            value = 0.
    elif spaced and lower in INDEPENDENT:
        value = -.10
    elif lower == 'itself' and spaced:
        value = .17
    elif spaced and lower in {'его', 'ее', 'её', 'их'}:
        value = .5
    elif spaced and romance > .7:
        value = FRENCH.get(lower, SPANISH.get(lower, value))

    if token.isspace() and token.count('\n') >= 2:
        if context.endswith('<think>'):
            value = .36
        elif context.endswith('</think>'):
            value = .30
    if token == '\f':
        value = .7
    if token == '\x00':
        last = context[-1:]
        value = 2.1 if last.isalpha() else .25 if last.isspace() else 1.1
    if '\\' in token:
        # A run of escapes can straddle two tokenizer pieces.
        tail = context[-8:]
        runs = [m for m in SLASHES.finditer(tail + token)
                if m.end() > len(tail)]
        if runs:
            nested = '\\"' in context or '\\n' in context
            value = (-1.4 if TEX.search(context)
                     else 1.45 if nested else 1.05)
            if len(runs[-1][0]) >= 3 and value > 0:
                value = max(value, 1.6)
    if lower in ENDINGS and token.isalpha():
        match = POSSESSIVE_WORD.search((context[-24:] + token).lower())
        if match and len(token) < len(match[1]):
            value = 1.5

    romance *= .9
    if lower in ROMANCE_CUES:
        romance += 1.
    elif lower in ENGLISH_CUES:
        romance = max(0., romance - .6)
    return (doc, (context + token)[-256:], lower, romance), float(value)

"""Detect standalone in-line padding, mostly ignoring ordinary words.

Strong negative responses mark tabs after digits and padding after table bars.
ASCII indentation and continuations of whitespace runs stay near zero;
nonbreaking-space tokens have separate negative baselines. Literal escaped
newlines do not reset padding detection. Numeric labels and table bars have
additional rules. Lengths below count characters in individual tokens.
"""
import re

READS = ()


def label(line):
    text = line.rsplit('\\n', 1)[-1].strip()
    marked = text.startswith(('#', '>', '//'))
    return re.sub(r'^(?:[#>/*]+\s*)+', '', text), marked


def response(s, previous, line):
    last = previous[-1:]
    if s and s.isspace() and '\n' not in s and '\r' not in s:
        if '\xa0' in s:
            return -0.33 if len(s) == 1 else -1.14
        if not last or last.isspace():
            return 0.15 if len(s) > 7 else 0.03
        if '\t' in s:
            if not previous.isdigit():
                return -0.94
            if s.count('\t') > 1:
                return -1.82
            n = s.count(' ')
            return (-3.95 if n == 0 else -3.45 if n <= 4
                    else -2.08 if n <= 8 else -1.33)
        if set(s) != {' '}:
            return 0.0
        if len(s) == 1:
            if line.endswith(('\\n', '\\t', '\\r')):
                return -2.9
            return -1.1 if label(line)[0].isdecimal() else -0.04
        if previous.strip() == '|':
            return -5.4 if len(s) <= 4 else -4.3 if len(s) <= 6 else -3.47
        if len(s) <= 6:
            if last.isalnum():
                return -3.0 if len(previous) == 1 else -1.44
            return -2.3
        if previous.startswith(' ') and not last.isalnum():
            return -1.7
        return -0.81 if len(previous) == 1 else -0.25
    if s.startswith('\t'):
        return (-0.84 if previous.isdigit() else
                -0.41 if last and not last.isspace() else 0.0)
    if s.strip() not in ('.', ')', '|') and not s.isdigit():
        return 0.0
    text, marked = label(line)
    if s.strip() in ('.', ')') and text.isdecimal():
        value = -0.95 if text == '1' else -0.32
        return value - 0.9 if marked else value
    if s.strip() == '|' and s.startswith(' '):
        return (-2.18 if text.isdecimal() else -1.26 if previous.isdigit()
                else -0.79 if not last or last.isspace() else 0.0)
    if s.isdigit() and not previous.isdigit() and not text:
        return -0.49 if line.strip() else -0.06
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    s = prefix.token_strings[-1]
    value = response(s, previous, line)
    line = (line + s).rsplit('\n', 1)[-1][-250:]
    return (doc, line, s), value

"""An unfinished para-/ara- spelling detector, including transliterated forms.

Another 'a' after ar- gives a positive response; e/i/o/u continuations of par-
give a negative one. Short fragments and consonant sounds adjust its size.
Param/XML tags and the paragraph/parasite families have separate responses.
A decaying count of Spanish/Portuguese versus English function words reduces
'para' when it looks like a preposition. Initial CRs and a comment-line marker
are secondary responses. This is a coarse spelling heuristic, not a word model.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
ROMANCE_WORDS = set((
    'de la el los las del que en un una con por se al lo su es '
    'os as do da dos das uma com nao ao um').split())
ENGLISH_WORDS = set((
    'the of and with for is are was were to from this that by it be can').split())

@lru_cache(maxsize=8192)
def roman(text):
    return anyascii(text).lower()


def last_word(text):
    match = re.search(r'[a-z]+$', text)
    return match.group()[-24:] if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word, language, blank = ('', '', 0., True) if first else carry[1:]
    token = prefix.token_strings[-1]
    s, p = roman(token), roman(previous)
    bare = s.strip(' \t\r\n_-.@')
    value = .001
    if bare == 'param':
        value += 1.33 + 2.71 * p.rstrip().endswith('<')
        value -= .42 * token.strip().startswith('P')
        value -= .37 * token.strip().isupper()
    elif bare == 'para':
        value += 2.67 - 2.55 * min(1., max(0., language) / 2.)
        value += 1.25 * first + 3.33 * p.rstrip().endswith('%')
        value += .41 * (p.strip() in {',', ';'})
    elif bare.startswith('paras'):
        value += 7.18 * (1. if len(bare) <= 5 else .4)
    elif bare.startswith('paragraph'):
        value += 1.32
    elif bare.startswith('para') and len(bare) <= 6:
        value += .31

    fragment = word if not token.isascii() and len(word) <= 5 else last_word(p)
    continuation = bool(s and s[0].isalpha() and word)
    if continuation:
        short = (max(2, len(s)) / 2.) ** -.7
        if s.startswith('ara') and len(s) <= 4:
            value += 1.3
        if len(fragment) <= 4 and re.search(r'ar+$', fragment):
            if s.startswith('a'):
                response = .56 + 1.01 * (len(s) <= 2)
                if fragment == 'par':
                    response += 2.56 - .37 * (len(s) <= 2)
                    if s[1:2] and s[1] in 'cgkqsxz':
                        response += 2.0
                    if not token.isascii() and s == 'a':
                        response += 3.5
                # The consonant immediately following this 'a'.
