                    ('cgkq', 1.45),    # velars
                    ('sxz', 2.31),     # sibilants
                    ('bpfv', -1.05),   # labials
                    ('dt', -.59),      # dentals
                    ('lry', -.66),     # liquids / glide
                    ('mn', .43),       # nasals
                ):
                    if s[1:2] and s[1] in letters:
                        response += adjustment
                value += short * response
            elif s[0] in 'eiou':
                value -= short * (.14 + .38 * (s[0] in 'ou')
                                  + 2.34 * (fragment == 'par'))
        elif len(fragment) <= 4 and re.search(r'pa[^aeiou\W]+$', fragment):
            if s.startswith('a'):
                value += .57 * short
            elif s[0] in 'eiou':
                value -= .17 * short
        if fragment.endswith('a') and s.startswith('ra'):
            value += 1.78 * short
        if fragment == 'pa' and s.startswith('r'):
            value += 1.82 + 1.97 * short * s.startswith('ra')
        if word.endswith('para'):
            value += short * (.92 + (not token.isascii())
                              * (.43 + 6.13 * (s[0] in 'gm')))
        if re.search(r'par[eiou][^aeiou]*$', word):
            value -= .54 * short
    elif bare.startswith('ara') and len(bare) <= 5:
        value += .32
    if blank and token == '\r':
        value += 6.46
    if first and token == '//\n':
        value += 10.58
    language = language * .97 + (s.strip() in ROMANCE_WORDS)
    language -= s.strip() in ENGLISH_WORDS
    return (doc, token, last_word(word + s), language,
            blank and token == '\r'), float(value)

"""Recognize separately tokenized blanks extending horizontal whitespace.

A space after several spaces is strong; after one space, a preceding
newline strengthens it. Repeated tabs are strong, repeated nonbreaking
spaces weaker. Repeated-space responses increase near document beginnings.
Assistant headers are mildly positive; user headers and chat delimiters
are negative. Other tokens are zero, except isolated spaces (-0.02).
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    t = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        p, pp, position = '', '', 0
    else:
        _, p, pp, position = carry

    value = 0.0
    if t == ' ':
        value = -0.02
        if p and not p.strip(' '):
            if len(p) == 1:
                value = 0.18 + 0.45 * pp.endswith('\n')
                value += 0.2 / math.sqrt(max(1, position))
            else:
                value = 1.0 if len(p) < 8 else 0.9
                value += 1.3 / math.sqrt(max(1, position))
    elif (t == '\t' and p.isspace() and p.endswith('\t')
          and '\n' not in p and '\r' not in p):
        value = 1.0
    elif t == '\xa0' and p and not p.strip('\xa0'):
        value = 0.35 if len(p) > 1 else 0.0
    elif p == '<|im_start|>':
        if t == 'assistant':
            value = 0.28
        elif t == 'user':
            value = -0.07
    elif t == '<|im_start|>':
        value = -0.04
    elif t == '<|im_end|>':
        value = -0.07

    return (doc, t, p, position + 1), value

