"""Layer-1 MLP down_proj, component 5286.

A sparse feature. It reads the current word together with the word just before it,
and its sign depends on what kind of word comes before:

* after a descriptor of people, nations or communities ("National", "International",
  "World", "young", "early", "recent", "Black", "citizens", "residents") it is
  positive, strongly so on the head of a fixed phrase: "National Park", "New Year",
  "young people", "recent years";
* after "no", "another" or a capital "A" a phrase head is positive ("no part",
  "no more", "another person", "A person"); after "a", "an", "any" or "every" it is
  only slightly positive ("any person" is weaker than "no part");
* after a plural or count quantifier ("some", "many", "two", "few") it is near zero
  or negative ("some more", "many other");
* after an office, title or institution word ("member", "Chief", "President",
  "Secretary", "Federal", "Central", "Title") it is negative: strongly on "of"
  ("member of", "Chief of", "President of") and on ":" in "Title:", and mildly on other
  words;
* "as" after a degree adjective ("early as", "high as", "close as") and "than" after a
  comparative ("later than") are positive; "of" after group nouns ("people of",
  "residents of", "citizens of") is positive;
* the first word of each document is slightly positive.

Everything else is predicted as 0. The numbers are rounded group means fitted on
training text, so the rules are words and the numbers are calibration."""

READS = ()

STRONG_DET = {"no", "another", "A"}
DET = {"a", "an", "any", "no", "every", "each", "another", "A"}
PEOPLE = {
    "National", "International", "World", "Public", "Republic", "republic", "Native",
    "African", "American", "Black", "black", "Living", "young", "older", "Older", "recent",
    "early", "rural", "remote", "corner", "citizen", "citizens", "residents", "fellow",
    "Veterans", "Foreign", "next", "Later", "later",
}
MOD = PEOPLE | {"New", "University", "high", "close", "large", "simple", "far", "further",
                "previous", "past", "Associated", "White", "white", "innocent"}
QUANT = {"some", "many", "two", "three", "few", "several", "one", "various", "among", "both",
         "most", "other"}
OFFICE = {"member", "Member", "Members", "Chief", "President", "president", "Secretary",
          "Governor", "Minister", "Vice", "Federal", "Central", "central", "Historic",
          "Related", "Global", "subject", "Title"}
GROUP = {"people", "residents", "citizens", "children", "victims", "officers", "men", "parts"}
PHRASE = {"person", "people", "men", "man", "women", "persons", "citizen", "citizens", "years",
          "cases", "case", "part", "time", "times", "more", "other", "matter", "citizenship"}
NAME = {"Year", "Park", "Press"}

# value for (previous word's class, current word's class), from group means on training text
TABLE = {
    ("DET", "PHRASE"): 0.3, ("DET", "OF"): 0.05,
    ("STRONG_DET", "PHRASE"): 1.4,
    ("MOD", "PHRASE"): 1.77, ("MOD", "NAME"): 3.93, ("MOD", "AS"): 1.9,
    ("MOD", "THAN"): 2.55, ("MOD", "OF"): 0.35,
    ("QUANT", "PHRASE"): -0.1, ("QUANT", "AS"): 0.42,
    ("OFFICE", "OF"): -1.0, ("OFFICE", "COLON"): -1.45, ("OFFICE", "PHRASE"): -1.5,
    ("GROUP", "OF"): 0.73,
}
FIRST_TOKEN = 0.16      # first word of a document
WORD_AFTER_PEOPLE = 0.2  # any other word after a people/nation descriptor
WORD_AFTER_OFFICE = -0.3  # any other word after an office/title word


def classify(w):
    if w in STRONG_DET:
        return "STRONG_DET"
    if w in DET:
        return "DET"
    if w in OFFICE:
        return "OFFICE"
    if w in QUANT:
        return "QUANT"
    if w in GROUP:
        return "GROUP"
    if w in MOD:
        return "MOD"
    return "OTHER"


def cur_class(w):
    if w in PHRASE:
        return "PHRASE"
    if w in NAME:
        return "NAME"
    if w in ("as", "than", "of", ":"):
        return {"as": "AS", "than": "THAN", "of": "OF", ":": "COLON"}[w]
    return "WORD" if w.isalpha() else "OTHER"


def step(carry, prefix, upstream):
    if len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, FIRST_TOKEN
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip()
    key = (classify(prev), cur_class(cur))
    if key in TABLE:
        return None, TABLE[key]
    if prev in PEOPLE and cur.isalpha():
        return None, WORD_AFTER_PEOPLE
    if prev in OFFICE and cur.isalpha():
        return None, WORD_AFTER_OFFICE
    return None, 0.0

"""Participle and relative-clause openers, negative.

Layer-1 MLP unit 5287 is mostly silent. It goes negative on the word that opens a modifier
attached to the phrase before it:
  - a relative word after "of": "many of WHICH", "both of WHOM"            (strongest)
  - a Russian relative pronoun or participle ending: "которого", "вовлеченные"
  - a concessive or subordinator: "though", "despite", "regardless"
  - a participle or -ing/-ed verb set off by a comma: ", SHOWING the ...", ", WRAPPING me"
  - a participle with no auxiliary before it: "a town KNOWN as", "a film DIRECTED BY"
  - a preposition after a quantifier or a participle: "each WITH", "located IN"
It is near zero on the same words after an auxiliary ("was directed by"), where the word
is a main-clause verb, and near zero on most other words.

Values are the rounded mean activation of each class on about 700 training rows
(512 positions each).
"""

READS = ()

AUX = {"is", "was", "were", "are", "be", "been", "being", "am", "has", "have", "had",
       "will", "would", "can", "could", "did", "does", "do"}
PARTICIPLES = {"known", "located", "referred", "consisting", "written", "spoken", "named",
               "born", "called", "featuring", "shown", "being", "having", "leading", "taking",
               "comprising", "describing", "resulting", "making", "standing", "causing",
               "allowing", "indicating", "suggesting", "providing", "producing", "using",
               "following", "creating", "looking"}
CONCESSIVES = {"though", "although", "despite", "regardless", "albeit"}
PREPOSITIONS = {"of", "to", "in", "by", "with", "as", "that", "for", "from", "at", "on"}
QUANTIFIERS = {"of", "each", "many", "all", "both", "some", "most", "two", "one", "five"}
RELATIVES = {"which", "whom", "whose"}

VALUE = {
    "relative_of": -3.8,     # "many of which", "both of whom"
    "russian": -1.5,         # Russian relative pronouns and participle endings
    "concessive": -0.6,      # though, although, despite, regardless
    "ing_after_comma": -0.7, # ", showing ..."
    "ed_after_comma": -0.5,  # ", named ..."
    "participle": -0.35,     # known, located, having ... (no auxiliary)
    "after_participle": -0.2,  # preposition after a participle: "named as", "born in"
    "after_quantifier": -0.2,  # preposition after a quantifier: "each with", "all in"
    "preposition_comma": -0.15,
    "relative_other": -0.13, # which/whom/whose elsewhere
}


def _lower(text):
    return text.strip().lower()


def _is_russian_relative(word):
    return any(stem in word for stem in ("котор", "ющ", "ящ"))


def step(carry, prefix, upstream):
    words = prefix.token_strings
    docs = prefix.document_ids
    word = _lower(words[-1])
    same_doc = [len(words) > k and docs[-1 - k] == docs[-1] for k in (1, 2)]
    prev = _lower(words[-2]) if same_doc[0] else ""
    prev2 = _lower(words[-3]) if same_doc[1] else ""
    aux = prev in AUX or prev2 in AUX
    comma = prev == ","

    if word in RELATIVES:
        if prev == "of":
            return None, VALUE["relative_of"]
        return None, VALUE["relative_other"]
    if _is_russian_relative(word):
        return None, VALUE["russian"]
    if word in CONCESSIVES:
        return None, VALUE["concessive"]
    if word in PARTICIPLES:
        return None, 0.0 if aux else VALUE["participle"]
    if comma and len(word) > 4 and word.endswith("ing"):
        return None, VALUE["ing_after_comma"]
    if comma and len(word) > 3 and word.endswith("ed"):
        return None, VALUE["ed_after_comma"]
    if word in PREPOSITIONS and not aux:
        if prev in QUANTIFIERS:
            return None, VALUE["after_quantifier"]
        if prev.endswith("ed") or prev in PARTICIPLES:
            return None, VALUE["after_participle"]
        if comma:
            return None, VALUE["preposition_comma"]
    return None, 0.0

programs.sol:
"""Approximate a file/stream-handling response using English words and local syntax.

File, directory and path vocabulary contributes a moderate response. File I/O
calls, their arguments and modes, shell redirection, module imports, and UTF-8
get context-dependent boosts. Identifier pieces have their own strengths.
A short suffix, reset for each document, supplies all context; no token-ID table
or model computation is used. Strengths were fitted on training examples.
"""
import re

READS = ()
# Words; whole-word strength; extra without leading space; identifier-piece strength.
VOCABULARY = (
    ({'file'}, 1.729, -0.007, 2.301),
    ({'files'}, 1.084, 0.188, 0.710),
    ({'filename', 'filenames'}, 2.583, 0.347, 3.920),
    ({'directories', 'directory'}, 1.876, 0.458, 2.812),
    ({'dir', 'folder', 'folders'}, 0.568, 0.770, 3.170),
    ({'filepath', 'path', 'pathname', 'paths'}, 1.071, 0.852, 2.716),
    ({'fdopen', 'fopen', 'open', 'popen'}, 0.106, 0.311, 0.592),
    ({'close', 'closed', 'fclose'}, -0.050, 0.081, 0.945),
    ({'fread', 'read', 'reader', 'readline', 'readlines'}, 0.216, 0.533, 1.542),
    ({'fwrite', 'write', 'writelines', 'writer'}, 0.029, 0.230, 0.191),
    ({'input', 'stdin', 'stdinput'}, 0.229, 0.218, 0.469),
    ({'output', 'stderr', 'stdout', 'stdoutput'}, 0.256, 0.233, 0.368),
    ({'dump', 'load', 'save'}, 0.224, 0.061, 0.757),
    ({'os'}, 0.677, -0.650, 0.476),
    ({'fs', 'io', 'sys'}, 1.058, -0.660, 1.177),
    ({'workspace'}, 0.153, 0.836, 0.173),
    ({'../', './'}, 2.117, -0.068, 0.000),
    ({'bash', 'python'}, 0.447, 0.076, 0.899),
    ({'exit'}, 1.162, -0.827, 1.159),
    ({'glob', 'listdir', 'scandir'}, 1.597, 0.000, 6.670),
    ({'chdir', 'makedirs', 'mkdir', 'rmdir', 'unlink', 'walk'}, 0.102, 0.565, 3.114),
    ({'eof'}, 0.747, 0.747, 0.863),
    ({'head', 'tail'}, 0.314, -0.304, -0.085),
    ({'cat'}, 0.691, 0.847, 0.000),
    ({'cd'}, 0.167, 0.822, 0.128),
    ({'fstream', 'ifstream', 'ofstream', 'stream'}, 0.428, 1.300, 1.095),
    ({'cstdio', 'cstdlib', 'iostream', 'stdio'}, 0.603, 0.603, 0.887),
    ({'line', 'lines'}, 0.213, 0.371, 0.751),
)
OPENERS = {'open', 'fopen', 'fdopen', 'popen'}
MODULES = {'os', 'io', 'fs', 'sys', 'glob', 'listdir', 'scandir'}
PARTS = re.compile(r'[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+|[0-9]+')


def file_response(s, previous, recent):
    value = 0.000
    w = s.strip()
    low = w.lower()
    # Code often appears inside an escaped JSON string.
    before = re.sub(r'\\+n', '\n', recent[-140:])
    before = re.sub(r'\\+t', '\t', before)
    before = re.sub(r'\\+(?=[\'"])', '', before)
    pieces = PARTS.findall(w.lstrip('._/'))
    words = {p.lower() for p in pieces}
    for group, whole, attached, piece in VOCABULARY:
        if low in group:
            value += whole
            if w and not s[0].isspace():
                value += attached
        elif words & group:
            value += piece
    if low == 'ir' and re.search(r'(?:cache|root|tmp|temp|work|home|base)d$', before):
        value += 6.208  # directory completion
    if (low in {'dir', '_dir', '_path', 'path'} and
            re.search(r'(?:tmp|temp|temporary)$', before, re.I)):
        value += 5.438  # temporary path
    if low == '_name' and re.search(r'file$', before, re.I):
        value += 3.055  # filename completion
    if low == 'directory' and re.search(r'working\s*$', before, re.I):
        value += 1.400  # working directory
    if words & OPENERS:
        if (low == 'open' and re.search(
                r'(?:^|\n)\s*(?:\d+\s+)?(?:async\s+)?with\s*$', before)):
            value += 8.574  # with open
        if re.search(r'(?:=|\breturn|\byield)\s*$', before):
            value += 4.583  # assigned open
        if w.startswith('.'):
            value += -0.193  # method open
    if (low in MODULES and
            re.search(r'\b(?:import|from)\s*$', before)):
        value += 3.400  # module import
    if low == 'fs' and re.search(r'\b(?:const|let|var)\s*$', before):
        value += 3.415  # module binding
    if low in {'f','fp','fh','fd','file'}:
        if (re.search(r'FILE\s*\*\s*$', before) or
                (re.search(r'\bas\s*$', before) and 'open(' in before)):
            value += 3.042  # file handle binding
    if low in {'file', '_file'} and re.search(r'(?:read|write|input|output)$', before, re.I):
        value += 3.662  # file io completion
    if {'read','write'} & words and 'file' in words:
        value += 1.782  # file io method
    formats = {'_csv', '_json', '_excel', '_table', '_pickle', '_parquet'}
    if low in formats and re.search(r'(?:read|write)$', before):
        value += 5.865  # serialization method
    # Syntax immediately after a file-opening call is particularly diagnostic.
    is_call = bool(re.search(r'\b(?:open|fopen|fdopen|popen)\s*$', before))
    if w.startswith('('):
        if re.search(r'(?:read|write)_(?:csv|json|excel|table|parquet|pickle)$', before):
            value += 2.449  # serialization call
            if '"' in w or "'" in w:
                value += 12.070  # serialization quoted call
        elif re.search(
                r'(?:readFile(?:Sync)?|writeFile(?:Sync)?|readlines|loadtxt|'
                r'savetxt|listdir|scandir|File|FileStream|StreamReader|'
                r'StreamWriter|Path|stat|unlink|remove|mkdir)\s*$', before):
            value += 0.351  # file api call
            if '"' in w or "'" in w:
                value += 3.195  # file api quoted call
    if is_call and w.startswith('('):
        value += 1.024  # opening call
        if '"' in w or "'" in w:
            value += 5.289  # opening quoted call
        if re.search(r'\bwith\s+open\s*$', before):
            value += 1.010  # with open argument
    if ('"' in w or "'" in w) and re.search(r'\b(?:open|fopen)\([^\n]{0,100},\s*$', before):
        value += 4.013  # mode quote
    if low in {'r','w','a','x','rb','wb','ab','rt','wt','r+','w+'}:
        if re.search(r'\b(?:open|fopen)\([^\n]{0,100},\s*[\'"]?$',before):
            value += 4.188  # file mode
    if low == 'file':
        if previous.strip().lower() == 'a':
            value += 0.992  # file indefinite
        if previous.strip().lower() == 'the':
            value += -0.068  # file definite
        if re.search(r'\bas\s*$', before):
            value += 0.593  # file as handle
        if re.search(r'\bopen\(', before):
            value += 2.310  # file near open
        if not s[0].isspace() or w[0].isupper():
            value += -0.078  # file identifier
    if low in {'in','out'} and re.search(r'(?:Std|std)$', before):
        value += 1.039  # std stream end
    if w == '8' and re.search(r'utf\s*-\s*$', before, re.I):
        value += 1.962  # utf8 digit
    if '<' in w and re.search(r'#\s*include\s*$', before):
        value += 1.302  # include angle
    if w in {'/', '"/', "'/", '../', '"../', "'../", './', '"./', "'./"}:
        value += 0.144  # path start
        if s[0].isspace():
            value += 0.260  # spaced path start
        if '"' in w or "'" in w:
            value += 0.603  # quoted path start
        if previous.strip() == 'cd':
            value += 1.032  # cd path
    if w in {'>', '>>'} and re.search(r'\b(?:cat|echo|printf)\b[^\n]*$', before):
        value += 5.556  # shell output redirect
    if '"' in w or "'" in w:
        if re.search(
                r'(?:filename|file_name|filepath|file_path|path|logfile)\s*=\s*$',
                before, re.I):
            value += 1.955  # assigned filename quote
        if re.search(r'path\.join\([^\n]{0,100},\s*$', before):
            value += 3.500  # path join quote
    if s.startswith('/main'):
        value += -1.282  # main path
    if s.startswith('/src'):
        value += -0.556  # source path
    if low == 'path' and re.search(r'[\'\"]\s*$', before):
        value += 1.258  # path key
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    token = prefix.token_strings[-1]
    value = file_response(token, previous, recent)
    return (doc, (recent + token)[-200:], token), float(value)

programs.haiku:
"""Files and paths: a "file-system" detector.

Layer-1 MLP unit 5288 is silent on most text. It fires on the words a program uses when it
names files, paths and directories, and on file-system calls:
  - file and path nouns, as code identifiers: file, path, dir, Directory, _file, FileName
    (strongest class, about 2.3)
  - the same nouns as plain English words after a space: " file", " directory" (about 1.6)
  - method calls on the file system after a dot: .listdir, .unlink, .mkdir, .makedirs,
    .readlines, .getcwd, .close (about 2.5)
  - relative path starts: "./" and "../" (about 2.4)
  - shell file commands: cat, cd, ls, rm, fs (about 0.9); os, open, stat, exists (about 0.3)
  - a bare "/" or " /", as in "cd /" (about 0.3)
Every other token is 0. The values are the mean activations of each class, least squares
fitted on training rows, so the program's variance explained is about 0.23 on them.
"""
import re

READS = ()

FILE_NOUNS = {"file", "files", "filename", "filenames", "filepath", "path", "paths",
              "dir", "dirs", "directory", "directories", "folder", "folders"}
METHODS = {"listdir", "unlink", "mkdir", "makedirs", "readlines", "getcwd", "close",
           "readfile", "writefile", "fopen"}
COMMANDS = {"cat", "cd", "ls", "rm", "fs"}
FS_CALLS = {"open", "os", "stat", "exists"}
CODE_NOUN, PROSE_NOUN, METHOD, RELATIVE_PATH = 2.3, 1.6, 2.5, 2.4
COMMAND, FS_CALL, SLASH = 0.9, 0.3, 0.3


def pieces(token):
    # Split camelCase and snake_case into lowercase words: "ReadFile" -> {"read", "file"}.
    return {p.lower() for p in re.findall(r"[A-Z]+(?![a-z])|[A-Z]?[a-z]+|\d+", token)}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    words = pieces(token)
    if words & FILE_NOUNS:
        value = PROSE_NOUN if token.startswith(" ") else CODE_NOUN
    elif token.startswith(".") and words & METHODS:
        value = METHOD
    elif words & COMMANDS:
        value = COMMAND
    elif words & FS_CALLS:
        value = FS_CALL
    elif token.strip() in ("/", '"/'):
        value = SLASH
    elif token.strip().startswith(("./", "../")):
        value = RELATIVE_PATH
    else:
        value = 0.0
    return carry, value

"""Clause introducers: the word that opens an embedded (reported or complement) clause.

The English conjunction 'that' is the main case, and its strength depends on the word before it:
  - after a verb of reporting or finding ('found that', 'shown that', 'said that'): strongest, ~3
  - after a verb of thinking or knowing ('know that', 'suggest that', 'assume that'): ~2
  - after a noun (relative 'that', 'the actions that'): weaker, ~1.2
  - after a preposition or 'do'/'for'/'of' ('in that', 'to that', 'do that'): ~0
  - sentence-initial demonstrative 'That': ~0.3
Equivalents in other languages ('que', 'che', 'что', 'dass', 'hogy', 'že') get ~1.
A Japanese topic comma ('は、') also opens a new clause and gets a moderate value.
Everything else is 0. The value is the expected activation at each token, not a fitted table:
the tiers are the sizes measured on a sample of training text.
"""
THAT = {" that", "that"}
THAT_CAPITAL = {" That", "That"}
FOREIGN = {" que", " che", " что", " dass", " daß", " hogy", " že"}
TOPIC_COMMA_PREV = {"は", "では", "には", "が"}
REPORT = {"found", "shown", "show", "shows", "showed", "said", "say", "says", "concluded", "conclude",
          "reported", "reports", "discovered", "testified", "revealed", "noted", "notes", "held",
          "claims", "claimed", "believed", "agreed", "realized", "confirmed", "observed", "announced",
          "declared", "insisted", "seen", "added", "confirms", "saying", "seems", "out"}
COGNITION = {"think", "thought", "believe", "know", "knew", "suggest", "suggests", "suggested",
             "indicate", "indicated", "indicates", "understand", "understood", "see", "realize",
             "demonstrated", "state", "states", "stated", "hope", "hoping", "remember", "mention",
             "mentions", "assume", "assumed", "assumption", "ensure", "ensures", "mean", "means",
             "implies", "argue", "claim", "prove", "learned", "learn", "agree", "expect", "sure", "aware"}
NOT_CLAUSE = {"in", "to", "of", "for", "with", "on", "from", "than", "but", "by", "at", "do", "does",
              "did", "into", "after", "as", "if", "like", "all", "given", "now", "about", "except"}

OBJECT_PRONOUNS = {"me", "you", "us", "him", "her", "them"}

def that_value(prev):
    if prev in REPORT or prev in OBJECT_PRONOUNS:
        return 3.0
    if prev in COGNITION:
        return 2.0
    if prev in NOT_CLAUSE:
        return 0.0
    return 1.2

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev_raw = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev = prev_raw.strip().lower()
    if tok in THAT:
        return None, that_value(prev)
    if tok in THAT_CAPITAL:
        return None, 0.3
    if tok in FOREIGN:
        return None, 1.0
    if tok == "、" and prev_raw in TOPIC_COMMA_PREV:
        return None, 0.8
    return None, 0.0

READS = ()

programs.sol:
"""Approximate a sparse collection of short linguistic constructions.

'Given that/this' is positive. Supplied-data descriptions in programming
problems are negative, particularly arrays, variable names, and ensuing
'return/find' requests. Negated 'any' and JSDoc type braces are also negative.
A bounded input-description state follows 'given'; a longer-lived problem
state recognizes output requests and headings. Formatting and document-start
rules are separate. These are heuristics, not a complete activation model.
"""
import re

READS = ()
TYPES = {'array', 'arrays', 'string', 'strings', 'integer', 'integers',
         'number', 'numbers', 'list', 'index', 'tree', 'collection',
         'matrix', 'graph', 'vector'}
MODIFIERS = {'positive', 'negative', 'non', 'binary', 'sorted', 'distinct',
             'signed', 'unsigned', 'nonnegative', 'lowercase', 'uppercase'}
FUNCTION_WORDS = {'of', 'and', 'the', 'to', 'with', 'from', 'that',
                  'will', 'is', 'are'}
NUMERALS = {'one', 'two', 'three', 'four'}
REQUESTS = {'return', 'find', 'output', 'convert', 'compute',
            'determine', 'calculate', 'check'}
ANNOTATIONS = {'param': -1.65, 'return': -2.25, 'returns': -1.0,
               'type': -0.4, 'typedef': -0.4}
CODE_TOPIC = re.compile(
    r'array|integer|string|algorithm|leetcode|geeksforgeeks|complexity|'
    r'\bSolved\b|binary|bit manipulation|problem (?:description|statement)',
    re.I
)


def input_pulse(token, word, prev, age):
    """Roles within a supplied-data description, not arbitrary token IDs."""
    if token == '\xa0':
        return -2.0
    if word in TYPES:
        if word in {'array', 'arrays'}:
            return -6.0 if prev.lower() == 'integer' else -3.2
        if word in {'string', 'strings'}:
            return -2.1
        if word in {'integer', 'integers'}:
            return -2.1 if age <= 2 or prev.lower() in NUMERALS else -1.2
        return -0.8
    if word in MODIFIERS:
        return -1.0
    if word in {'-empty', '-negative'}:
        return -2.2
    if (prev.lower() in TYPES and word not in FUNCTION_WORDS
            and re.fullmatch(r'[a-z]{1,4}', word)):
        if not token.strip().islower():
            return -0.6
        if word.startswith('num'):
            return -3.2
        return -2.7 if prev.lower() == 'string' else -1.6
    if token.strip() in {',', 'and', 'of'}:
        return -1.3 if word == 'of' and prev.lower() in TYPES else -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous, position = '', '', 0
        age, typed, capital, problem_age, pending = 100, False, False, 1000, 0
    else:
        (doc, text, previous, position, age, typed, capital,
         problem_age, pending) = carry
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip()
    age, problem_age = age + 1, problem_age + 1
    value, next_pending = (-0.08 if position == 0 else 0.0), 0

    if word == 'given':
        age, typed = 0, bool(CODE_TOPIC.search(text[-180:]))
        capital = token.strip() == 'Given' or bool(re.search(
            r'\byou are(?: also)?\s*$', text, re.I))
    elif age == 1 and not (word in TYPES | NUMERALS | {'a', 'an', 'the'}
                           or re.fullmatch(r'[a-z]', word)):
        age, typed = 100, False
    if age <= 8 and word in TYPES | {'sorted', 'binary', '-empty',
                                     '-negative', '-index'}:
        typed, problem_age = True, 0
    frame = typed and age <= 32
    strength = 1.0 if capital else 0.5

    if position == 0 and token == 'class':
        value = -1.63
    elif position == 1 and text == 'Title' and token == ':':
        value = -7.10
    elif token == ':' and re.fullmatch(r'-{3}\s+title', text):
        value = -1.5
    elif token in {' {', ' {{'} and re.search(r'@\w+\s*$', text):
        value = ANNOTATIONS.get(prev, 0.0)
    elif token == '\xa0' and prev == '`':
        value = -1.7
    elif word in {'any', 'anything'}:
        if re.search(r'\bwithout\s*$', text, re.I):
            value = -0.95
        elif re.search(r'\bnot\s+produce\s*$', text, re.I):
            value = -0.6 - 2.0 / (position + 3) ** 0.5
        elif (word == 'any' and prev.lower() not in
              {'in', 'to', 'of', 'with', 'on', 'by', 'for', 'under'} and
