import re

READS = ()
# Conventional lifecycle callbacks: startup, a main loop, and its drawing work.
LIFECYCLE = {
    'init', 'initialize', 'setup', 'start', 'awake', 'oncreate',
    'viewdidload', 'ngoninit', 'run', 'execute', 'loop', 'update',
    'paint', 'render', 'build',
