    if name.lower() == 'main':
        if re.search(r'\bint\s*$', declaration):
            value = 10.0
        elif re.search(r'\bdef\s*$', declaration):
            value = 8.0
        elif re.search(r'\b(func|fn)\s*$', declaration):
            value = 6.5
        elif re.search(r'\bvoid\s*$', declaration):
            value = 5.8
        elif before.endswith('__'):
            value = 4.8
        elif re.search(r'\bpackage\s*$', declaration):
            value = 2.5
        elif word.startswith(('/', '_', '.')):
            value = 1.2
        elif before.endswith('Test'):
