    elif name in ('args', 'argc') and re.search(r'\b[Mm]ain\s*\([^\n]*$', before):
        value = 6.0 if name == 'args' else 3.0
    elif word == 'default':
        value = 4.9 if re.search(r'\bexport\s*$', before) else 0.1
    elif word == 'construct' and before.endswith('__'):
        value = 4.4
    elif name == 'init':
        constructor = bool(re.search(r'\bdef\s+__$', line))
        value = 1.7 if constructor else (2.0 if declared else 0.7)
    elif name == 'constructor':
        value = 2.8
    elif name.lower() in LIFECYCLE:
        value = 2.0 if declared else (1.4 if word.startswith('.') else 0.1)
    elif name.lower() == 'new':
        if declared:
            value = 2.5
        elif before.endswith('::'):
            value = 1.4
        elif word.startswith('.'):
            value = 0.8
    elif word == '.exports':
        value = 1.8
    elif word in ('<head', '<body') or (word in ('head', 'body') and before.endswith('<')):
        value = 3.0
    elif word.startswith('__') and re.search(r'__main$', before):
        value = 1.8
    elif name.lower() == 'app':
        if re.search(r'create$', before):
            value = 4.5
        elif re.search(r'\b(const|var|let)\s*$', before):
            value = 2.6
        elif before.endswith('My'):
            value = 1.8
        elif code or word.startswith(('.', '(')):
