    elif re.fullmatch(r'[A-Z][a-z]+App', name):
        value = 1.8
    elif name.lower() in ('root', 'window', 'scene'):
        value = 0.8 if code or not token[:1].isspace() else 0.15
    elif word == 'single':
        value = 0.6 if re.search(r'\ba\s*$', before) else 0.05
    # Smaller cues from argument lists, assignments, and block openings.
    elif word in ('()', '():', '(){', '();'):
        if re.search(r'\b[Mm]ain\s*$', before):
            value = 4.5 if word == '():' else 2.8
        elif word == '();':
            value = 0.2
        elif token[:1].isspace() or re.search(r'\bfunction\s*$', before):
            value = 1.4
        elif re.search(r'\b(init|initialize|start|Awake|onCreate|setup|loop)\s*$', before):
            value = 2.8
        elif re.search(r'\b(def|func|fn|public|private|void)\b', line):
            value = 1.0
        elif re.search(r'\.\w+$', before):
            value = 0.2
        else:
            value = 0.5
    elif word == '=':
        if re.search(r'\b(module\.exports|app|MyApp)\s*$', before):
            value = 2.7
        elif re.search(r'\b[ijk]\s*$', before):
            value = -0.4
        elif re.search(r'\b(const|let|var)\s+\w+$', line):
            value = 0.8
        elif re.search(r'\b(parser|config|builder|server|client|response|result)\s*$', line):
            value = 0.9
        elif re.search(r'\.\w+\s*$', line):
            value = 0.1
        elif re.search(r'\b\w{3,}\s*$', line):
            value = 0.3
        else:
            value = 0.1
    elif word in ('(', '[', '{') and ('\n' in token or token.endswith('\\')):
        if re.search(r'\breturn\s*$', line):
            value = 1.8
        elif word == '{':
            value = 1.2 if re.search(r'\bmain\s*\(\)\s*$', line) else 0.0
        else:
            value = 0.5
    elif word == '):' and '\n' in token:
        value = -0.8 if re.search(r'\bdef\b', line) else -0.1
    elif word == 'return':
        value = 0.2
    return (doc, tail), value

programs.haiku:
"""Function-definition detector for layers.1.mlp.down_proj:5291.

The component fires on the name of a function being defined in source code, most
strongly when that name is `main` (`int main`, `func main`, `void main`), on `args` in
`main(String[] args)`, on `default` in `export default`, and on framework or entry-point
names that open a definition (init, run, Awake, Start, constructor). It also fires weakly
on `=` and `(` in declaration lines (const x =, let x =, module.exports =).

Everything else predicts 0: the bulk of small activations, the negative values, and the
first token of each document are not captured by these rules."""
READS = ()

# keywords that open a function or method definition in common languages
DEF = {"func", "fn", "def", "function", "void", "int", "export", "fun", "public", "static"}
# keywords that bind a name on a line (variables, functions, exports)
DECL = DEF | {"const", "let", "var", "my", "async", "private"}
# names of program entry points and framework hooks, which start a definition
ENTRY = {"init", "run", "start", "Start", "Awake", "loop", "paint", "Update", "initialize", "build", "handle", "render"}
CTOR = {"constructor", "__construct"}

def step(carry, prefix, upstream):
    toks = [t.strip() for t in prefix.token_strings]
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    # tokens on the current line, before this one
    i = len(toks) - 1
    while i > 0 and "\n" not in prefix.token_strings[i - 1]:
        i -= 1
    in_decl = any(t in DECL for t in toks[i:-1])
    if cur in ("main", "Main") and prev in DEF:
        return carry, 6.2          # int main, func main, void main
    if cur == "args" and prev.endswith("[]"):
        return carry, 5.9         # main(String[] args)
    if prev == "export" and cur == "default":
        return carry, 4.8
    if cur in CTOR or (prev in DEF and cur in ENTRY):
        return carry, 2.0
    if cur in ("main", "Main"):
        return carry, 0.8
    if in_decl and cur == "=":
        return carry, 0.4
    if in_decl and cur in ("()", "("):
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""A partial spelling-based approximation, rather than a topic detector.

Positive pulses favor short p--r/l--t roots: port, profit, spirit, polit-.
Token splits, inflections and 'spirit of' modify the pulse. Greek pro-
and several Cyrillic continuations receive negative pulses; Cyrillic
pri/por syllables have additional positive rules. Separate rules handle
middle dots and document-initial title/comment headers.
State keeps the unfinished word, previous token and document position,
resetting at document boundaries. Other contextual variation is unmodeled.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()
ROOT = re.compile(
    r'p(?:r[aeiou](?:[nf][aeiou]?)?|[aeiou][rl][aeiou]?n?)'
    r't(?:s|ed|ing|[aeiou])?$'
)


def frame(text):
    return bool(ROOT.fullmatch(text))


def predict(piece, tail, previous, position):
    s = anyascii(piece).lower()
    bare = s.strip(' \n\t._/-(')
    continued = bool(piece and piece[0].isalpha() and tail)
    word = tail + piece.lower() if continued else piece.lower().lstrip()
    roman = anyascii(word).lower()
    root = roman[roman.rfind('p'):] if 'p' in roman else ''
    local = bare[bare.rfind('p'):] if 'p' in bare else ''
    value = 0.0

    # Short root contained in this token.
    if (piece.isascii() and frame(local)
            and bare in (local, 's' + local, 'non' + local)):
        other_vowels = any(v in local for v in 'aeu')
        value = 0.42 - 0.39 * other_vowels
        if 'f' in local:
            value += 1.18
        if bare.startswith('s'):
            value += 0.93
        if local.startswith('pr'):
            value += 0.45 - 0.73 * other_vowels
        spirit_frame = bool(re.match(r'p[oi]r[oi]t', local))
        if local.endswith('s') and bare.startswith('s') and not spirit_frame:
            value -= 0.67
        if local.endswith('ed'):
            value += 0.37 + 2.66 * spirit_frame
        if local.endswith('ing'):
            value -= 0.52
        if bare == 'print':
            value -= 0.71
            if previous.strip().lower() in ('in', 'of'):
                value += 1.70
        if piece.startswith('-') and 'f' in local:
            value += 3.28
        if local == 'port' and piece[0].islower():
            value += 1.51

    # Root completed across a token boundary.
    if (piece.isascii() and continued and frame(root)
            and 't' in s and not frame(local)):
        value += 2.54
        stem = re.sub(r'(s|ed|ing|[aeiou])$', '', root)
        if not any(v in stem for v in 'io'):
            value -= 1.40
        if 'l' in root:
            value -= 0.93
        if re.match(r'p[oi]r[oi]t', root):
            value += 4.16
        if len(s) > 1:
            value -= 0.80

    # Greek pro-: its vowel, then its following consonant.
    greek = unicodedata.normalize('NFD', word)
    greek = ''.join(c for c in greek if not unicodedata.combining(c))
    if greek.endswith('προ') and not piece[0].isspace():
        value -= 2.87
    if (len(greek) >= 4 and greek[-4:-1] == 'προ'
            and greek[-1] not in 'αεηιουω'):
        value -= 3.66

    # Cyrillic root/syllable pulses and fricative continuations.
    if any('CYRILLIC' in unicodedata.name(c, '') for c in piece):
        if re.search(r'прин?$', word):
            value += 0.17 + 0.33 * continued + 1.65 * word.endswith('прин')
        if frame(root) and 'т' in piece.lower():
            value += 0.64 + 2.05 * root.startswith('por')
            value += 0.28 * root.startswith('pir')
            if 'a' in root and 'i' not in root:
                value -= 0.68
        if continued and piece.lower() in ('при', 'пор'):
            value += 2.15
        if re.search(r'(?:пр[ое]ж|прош|пораж)$', word):
            value -= 2.14
    if word.endswith('порой'):
        value -= 2.11
    if bare == 'poi':
        value -= 1.00
    if bare == 'of' and previous.strip().lower() == 'spirit':
        value += 1.76

    # Separate formatting effects.
    if piece == '··':
        value -= 1.71
    if position == 0 and piece == '//\n':
        value -= 3.52
    if position == 1 and piece == ':' and previous == 'Title':
        value += 6.40
    return value, word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = '', '', 0
    else:
        _, tail, previous, position = carry
    piece = prefix.token_strings[-1]
    value, word = predict(piece, tail, previous, position)
    match = re.search(r'[^\W\d_]+$', word)
    tail = match.group()[-32:] if match else ''
    return (doc, tail, piece, position + 1), value

"""A detector for unordered-list and section markers.

A hyphen or asterisk is strongest at the beginning of a line, rather than
inside a word or expression. A colon introducing a list boosts the response;
ordinary repeated items are weaker. Escaped newlines also count. Geometric
bullets, middle dots, and checkmarks have their own response strengths.
Indented asterisks are downweighted, as in block comments. Other text gets zero.
"""
import re

READS = ()
ROUND = set('•●○◦')
SHAPES = set('■▪▫□◆◇♦')
TRIANGLES = set('▼▶►△▲')
CHECKS = set('✓✔☑')
MARKERS = ROUND | SHAPES | TRIANGLES | CHECKS | set('-*–—・·§o')


def marker_value(symbol, token, context, previous, escaped=False):
    whitespace = re.search(r'\s*\Z', context)[0]
    before = context[:len(context) - len(whitespace)] if whitespace else context
    last = before[-1:]
    line_start = '\n' in whitespace
    blank = whitespace.count('\n') > 1
    prev_line = before.rsplit('\n', 1)[-1]
    repeated = any(ch in prev_line for ch in '•✓-')
    leading_space = token[0].isspace()
    colon = last in {':', '：'}

    if symbol == '-':
        if re.search(r'(?m)^[ \t]*(?://|\*)[ \t]*\Z', context):
            return 2.7 if escaped else 1.5
        if line_start:
            if escaped:
                return 2.9 if leading_space else 2.5
            if colon:
                return 1.3 if blank else 3.0
            return 0.8 if repeated else 1.1
        if colon:
            return 0.6
        if last == '.':
            return 0.45
        return 0.65 if previous.isspace() else 0.0
    if symbol == '*':
        if colon:
            return 1.5
        if not line_start:
            return 0.0
        if leading_space:
            return 0.35 if escaped else 0.08
        return 0.45 if '*' in prev_line else 0.95
    if symbol in ROUND:
        if colon:
            return 3.7
        if not line_start:
            if last.isdigit() or symbol != '•':
                return 0.1
            return 2.3
        if symbol in '○◦':
            return 3.9
        if repeated:
            return 1.3 if last.isdigit() else 1.9
        return 2.3 if blank else 2.8
    if symbol in CHECKS:
        if '\n' in previous:
            return 1.05 if leading_space else 1.9
        return 0.45 if line_start else 0.25
    if symbol in '・·':
        if line_start and colon:
            return 5.0
        return 3.8 if line_start else (1.0 if leading_space else 0.0)
    if symbol in '–—':
        return 1.3 if line_start else -0.06
    if symbol in SHAPES:
        return 2.8 if line_start or colon else 0.1
    if symbol in TRIANGLES:
        return 1.5 if line_start else 0.1
    if symbol == '§':
        if line_start:
            return 1.0 if previous.isspace() else 3.4
        return 0.0
    if symbol == 'o':
        return 2.0 if line_start else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    symbol = token.strip()
    if '\ufffd' in token:
        same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == doc
        parts = prefix.token_bytes[-2:] if same_doc else prefix.token_bytes[-1:]
        joined = b''.join(parts).decode('utf8', 'replace')
        if joined[-1:] in MARKERS:
            symbol = joined[-1]
            tail = tail.rstrip('\ufffd')
    value = 0.0
    if symbol in MARKERS:
        context = tail.replace('\\n', '\n').replace('\\t', '\t')
        value = marker_value(symbol, token, context, previous, '\\n' in tail[-20:])
    return (doc, (tail + token)[-240:], token), value

programs.haiku:
"""Line-initial list markers.

Component layers.1.mlp.down_proj:5294 responds to the marker that opens a line of a
bulleted or dashed list: •, -, *, ✓, ・, ·, – and similar, when it is the first
thing on its line. Mid-line dashes, asterisks and bullets (x - y, 2*3, a-b) give
nothing, and neither does any other text.

How strongly it responds depends on the line before the marker:
  - after a line ending in a colon ("These include:"), a list is starting: strong;
  - after another bullet item, the list is already going: weaker;
  - after ordinary text: in between.

The program tracks the current and previous line (its carry) and writes the size
of the marker, or 0 everywhere else.
"""

# Typical size of each marker opening a line after ordinary text.
MARKER = {
    "・": 5.5, "♦": 5.2, "–": 4.6, "○": 4.5, "·": 3.8, "•": 3.0, "✓": 2.3,
    "-": 1.4, " -": 2.0, "*": 0.9, " ✓": 0.7,
}
# How the previous line scales a marker.
AFTER = {"colon": 1.5, "text": 1.0, "bullet": 0.8}
# Characters that start a bullet line; a line starting with one counts as a bullet item.
BULLET_START = set("•・·✓–-*○■♦►△★§")
READS = ()


def is_newline(tok, prev):
    """A real line break, or the two characters \\n written out in text."""
    return "\n" in tok or tok == "\\n" or (tok == "n" and prev.endswith("\\"))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else "\n"
    last, has_text, first_bullet, end = carry if carry else ("none", False, False, "")
    value = 0.0
    if not has_text and tok in MARKER:
        value = MARKER[tok] * AFTER.get(last, 1.0)
    # update the line state with this token; a line break closes the line
    if is_newline(tok, prev):
        if has_text:
            if end == ":":
                last = "colon"
            elif first_bullet:
                last = "bullet"
            else:
                last = "text"
        has_text, first_bullet, end = False, False, ""
    elif tok.strip():
        if not has_text:
            first_bullet = tok.strip()[0] in BULLET_START
        has_text = True
        end = tok.strip()[-1]
    return (last, has_text, first_bullet, end), value

