import re

READS = ()
MODIFIERS = re.compile(
    r'\b(?:public|private|protected|static|final|const|typedef|inline|extern)\s*$'
)
CONVERSIONS = re.compile(
    r'\b(?:map|range|append|isinstance|str|print|format|defaultdict)'
    r'\b[^;{}]*$'
