"""A mostly negative recognizer of C-family library and type syntax.

Allocation calls (especially after pointer casts) and C headers get large
negative values. File/string operations, resource-management verbs, pointer
types and identifier suffixes have smaller, category-specific predictions.
The numbers are category means measured on training text, not a token table.
A 160-character tail helps join identifier fragments. A document-reset flag
remembers C-like declarations, directives or comments. Other text gets zero.
This approximates the feature; it does not reproduce all contextual variation.
"""
import re

READS = ()

C_HEADERS = set("""
    stdio stdlib string math time assert ctype errno limits float locale
    signal setjmp stddef stdint stdbool
""".split())
OPERATIONS = set("""
    get set init add remove read write free dump clear enable disable create
    open close update copy replace reset change exists pop push gen generate
    lock unlock allocate deallocate
""".split())
LIST_PARTS = set('list head tail next prev'.split())
C_TYPES = r'(?:char|int|float|double|void|long|short|unsigned|FILE|\w+_t)'
C_CLUE = re.compile(
    r'#\s*(?:include|define)|\b(?:typedef|static|extern)\b|/\*|\*/|'
    r'\b(?:char|int|float|double|void|unsigned)\s+[\w*]|\bstd::'
)
BUILTIN_POINTER = re.compile(r'\b'+C_TYPES+r'\s*$|\bstruct\s+\w+\s*$')
USER_POINTER = re.compile(r'(?:\b[A-Z]\w+|\b\w+_\w+)\s*$')


def activation(token, before, c_code):
    s = token.strip()
    word = re.search(r'[A-Za-z_][\w/]*\Z', before)
    prev = word.group(0) if word else ''
    # C and POSIX headers.
    if s.startswith('<') and s[1:] in C_HEADERS:
        return -0.5
    if s == '.h':
        if prev in C_HEADERS:
            return -7.32
        if prev in {'unistd', 'types', 'sys/types'}:
            return -3.12
        return -0.85
    if s == 'stdlib':
        return -7.56
    if s == 'stdio':
        return -4.5
    if s == 'unistd':
        return -3.75
    # Allocation calls and pointer-cast context.
    if s in {'malloc', 'calloc', 'realloc'}:
        if re.search(r'\*\s*\)\s*$', before):
            return -7.82
        if c_code and re.search(r'[=(,]\s*$', before):
            return -6.32
        return -3.11
    if s in {'printf','scanf','fprintf','sprintf','snprintf'}:
        if not token[0].isspace() and prev:
            return -5.08
        if s == 'fprintf':
            return -3.11
        return -1.42
    if s in {'gets','close'} and prev in {'f','p'}:
        return -3.12
    if s in {
        'perror', 'feof', 'fflush', 'fgets', 'fopen',
        'fclose', 'atoi', 'atof', 'strerror', 'errno',
        'fread', 'fwrite', 'fgetc', 'fputc', 'fseek',
        'ftell', 'rewind', 'ungetc', 'freopen',
    }:
        return -2.1
    if s == 'free' and c_code:
        return -0.58
    if s in {
        'strcpy', 'strncpy', 'strcmp', 'strncmp', 'strcat',
        'strlen', 'memcpy', 'memset', 'memcmp',
    }:
        return -0.85
    if s in {'cat','cpy','cmp','len','set','move'} and prev.lower() in {'str','mem'}:
        return -4.08
    if s == '_replace' and prev.lower().endswith('str'):
        return -2.39
    # Underscore-separated API names, types and constants.
    if s.startswith('_') and s[1:].isalpha():
        part = s[1:]
        if prev in {'array','str','mysqli'}:
            return -3.33
        if prev == 'va':
            return -3.25
        if part.lower() in {'alloc','free','malloc','calloc','realloc'} and c_code:
            return -4.06
        if s == '_t':
            is_type = bool(re.fullmatch(
                r'(?:s?size|u?int[0-9]*|socklen|time|ptrdiff|double|float|option)',
                prev.lower()))
            return -1.03 if c_code or is_type else 0.0
        if part.isupper():
            return -0.27 if c_code else -0.09
        if part.lower() in OPERATIONS:
            return -2.57 if c_code else 0.0
        if part.lower() in LIST_PARTS:
            return -0.87 if c_code else 0.0
        return -0.13 if c_code else 0.0
    # Pointer declarations and casts.
    if s in {'*','**','*)','**)'}:
        if BUILTIN_POINTER.search(before):
            return -2.68
        if c_code and USER_POINTER.search(before):
            return -1.23
    if s == 'NULL':
        return -1.34 if c_code or re.search(r'[!=]=\s*$', before) else 0.0
    # Operation verbs inside CamelCase API names.
    if (c_code and token == s and prev and s[0:1].isupper()
            and s.lower() in OPERATIONS):
        if s.lower() in {'free','lock','unlock','allocate','deallocate'}:
            return -4.33
        return -0.14
    if s == 'struct' and re.search(r'\btypedef\s*$', before):
        return -2.11
    if s == '#include':
        return -0.37
    if s in {'.c','.cpp'}:
        return -0.16
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, c_code = '', False
    else:
        _, before, c_code = carry
    token = prefix.token_strings[-1]
    text = before + token
    c_code = c_code or bool(C_CLUE.search(text[-160:]))
    value = activation(token, before, c_code)
    return (doc, text[-160:], c_code), float(value)

