    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if prefix.position > 0 else ""
    if cur in ALLOC:
        return None, -8.0 if prev in ("*)", "*") else -3.4
    if cur in CALLS:
        return None, -2.5
    if cur in HEADERS:
        return None, -4.0
    if cur == ".h":
        return None, -6.7 if prev in HEADERS else -1.5
    if cur == "*)":
        return None, -1.5
    if cur == "_replace" and prev == "str":
        return None, -2.4
    if cur == "_t":
        return None, -0.9
    return None, 0.0

