"""Layer-1 MLP down-projection unit 5301.

A code-comment / cross-reference detector with two signs:
- a '#' that opens a comment or markdown heading (or a C '#include' directive) pushes it up,
  most at the start of a line; '//' comment markers push it up a little;
- a Javadoc/JSDoc tag name after '@' or '{@' ('see', 'link', 'since') pushes it strongly down;
  bare 'see' and '.md' file links push it down a little; a '#' in a markdown anchor `](#...)`
  pushes it down.
"""

READS = ()

HASH_LINE_START = 0.9
HASH_INLINE = 0.3
SLASH_COMMENT = 0.25
JAVADOC_TAGS = {"see": -6.4, "link": -4.8, "linkplain": -3.4, "since": -3.2}
XREF = {"see": -0.5, "See": -0.3, "also": -0.1, ".md": -0.25}
MD_ANCHOR = -1.0


def _line_start(strings, i):
    """True if token i is the first non-blank token on its line."""
    j = i - 1
    while j >= 0 and strings[j].strip(" \t") == "" and "\n" not in strings[j]:
        j -= 1
    if j < 0:
        return True
    return "\n" in strings[j] or strings[j].endswith("\\n")


def step(carry, prefix, upstream):
    s = prefix.token_strings
    i = prefix.position
    tok = s[i].strip()
    prev = s[i - 1] if i > 0 else ""
    if tok in JAVADOC_TAGS and prev.rstrip().endswith("@"):
        return None, JAVADOC_TAGS[tok]
    if tok == "#":
        if prev.endswith("]("):
            return None, MD_ANCHOR
        return None, HASH_LINE_START if _line_start(s, i) else HASH_INLINE
    if tok == "#include":
        return None, 0.4
    if tok == "//":
        return None, SLASH_COMMENT
    if tok in XREF:
        return None, XREF[tok]
    return None, 0.0

