"""Respond to separators in paths, dates, and other slash-delimited forms.

The strongest cases are another slash after a numeric date field, a glob's
/**, a /s/ signature, or the example path/to. Ordinary path separators and
root-directory names get smaller responses. Repeated ASCII branch strokes
are positive too; ordinary prose alternatives are usually negative.
Only a short trailing text buffer is retained, reset at document boundaries.
"""
import re
import calendar

READS = ()
ROOT_DIRS = {'usr', 'opt', 'tmp', 'root', 'home', 'workspace', 'testbed',
             'var', 'etc', 'dev', 'mnt', 'srv', 'bin', 'lib', 'Users'}
SOURCE_DIRS = {'src', 'tests', 'test', 'docs', 'examples', 'node_modules',
               'packages', 'crates', 'build', 'dist', 'internal'}
MEDIA_TYPES = {'application', 'audio', 'font', 'image', 'message', 'model',
               'multipart', 'text', 'video'}
MONTHS = set(calendar.month_abbr[1:])


def predict(text, prev, token):
    field = re.search(r'[^\s\"\'<>`{}()]*$', text).group()
    last = re.split(r'[/\\]', field)[-1]
    in_path = '/' in field or '\\' in field
    url = '://' in field
    stroke = token.strip()
    line = text.rsplit('\n', 1)[-1]
    if stroke in {'/', '\\'} and re.fullmatch(r'[ /\\]+', line):
        if '/' in line or '\\' in line:
            return 8.0
    if not text and token in {'/', ' /', ' \"/'}:
        return 4.0
    distance = len(text) - text.rfind('/') - 1 if '/' in text else 999
    if token == ' /' and distance < 3:
        return 4.3
    if token in {"'/", '"/'} and distance < 3:
        return 4.9
    if token == '\\' and text.endswith('/**'):
        return 4.0
    if token == '/':
        number = re.search(r'/(\d{1,3})$', text)
        if number:
            return 5.0 if url else (6.2 if len(number[1]) == 3 else 7.6)
        if field.endswith('/**'):
            return 8.7
        if field.endswith('/s'):
            return 7.5
        if last in MONTHS and '/' in field:
            return 5.0
        if last in ROOT_DIRS:
            if last == 'opt':
                return 4.8
            return 4.0 if last == 'workspace' else 3.0
        if url and field.count('/') <= 2:
            return 0.1
        if last in SOURCE_DIRS:
            return 2.2 if in_path else 1.1
        if last in MEDIA_TYPES:
            return 1.0
        if in_path:
            if last and last[-1].isdigit():
                return 0.8
            return 0.6 if url else 2.1
        if re.search(r'/[ \t]{2,}[^ \t]+$', line):
            return 2.2
        if field.startswith('.'):
            return 0.8
        if text and text[-1].isdigit():
            return -0.15
        return -0.8 if text and text[-1].isalpha() else 0.0
    if token.startswith('/') and not token.startswith('//'):
        tail = token[1:]
        if tail == 'to' and last == 'path':
            return 10.5 if in_path else 6.6
        if token == '/\n':
            return 2.1
        if tail == 'local' and last == 'usr':
            return 3.8
        if tail == 'python':
            return 2.2
        if tail == 'bin':
            return 2.0 if last == 'local' else 1.3
        if tail == 'workspace':
            return 0.8
        if tail.startswith('__'):
            return -0.7
        if tail.startswith('.'):
            return 1.2 if in_path else 0.2
        if tail and tail[0].isalnum():
            if last in ROOT_DIRS:
                return 1.8
            if tail.lower() == 'or':
                return 0.7
            if in_path:
                return 0.9 if len(tail) <= 2 else 0.35
            return -0.25
    if token == '__/':
        return 1.2
    if prev.rstrip().endswith('/') and token in ROOT_DIRS:
        return 1.8 if token == 'workspace' else 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, prev = '', ''
    else:
        _, text, prev = carry
    token = prefix.token_strings[-1]
    value = predict(text, prev, token)
    return (doc, (text + token)[-200:], token), value

