    if joins and 'integ' in whole:
        if whole.endswith(('integer', 'integers', 'integrity')):
            return 0.0
        if 'integ' not in prev:
            if whole.endswith('integral'):
                return -0.8
            return -11.5 if whole.endswith(('integ', 'integr')) else -6.0
        if prev.endswith('integ'):
