    if joins and whole.startswith('entreg') and 'entreg' not in prev:
        return -9.0
    if joins and piece in ('eg', 'egr') and prev.endswith('nt'):
        return -8.0
    if joins and prev in ('int', 'inter') and piece in ('g', 'gr', 'reg', 'gal'):
        return -6.5
    if joins and prev.endswith('intergr') and piece.startswith('at'):
        return -6.5
    if joins and prev.endswith('te') and len(piece) <= 3:
        if piece.startswith('g') or piece == 'br':
