        return -5.6
    if token in ('贸', '贸易', '外贸'):
        return -1.9
    if word.startswith('focal'):
        return -4.4
    if word.startswith('fisc'):
        return -1.2
    if word.startswith('fret'):
        return -2.4
    if word == 'fec' or word.startswith(('feca', 'fece')):
        return -1.0
    if previous.lower().endswith(('fec', 'fa')):
