        return -6.3
    if fragment.startswith('ret'):
        return -2.8
    if fragment.startswith('inal'):
        return 2.0
    if fragment.startswith('ix'):
        return 3.5 if fragment.endswith('er') else 0.3
    if fragment.startswith(('ic', 'id', 'is')):
        return -0.3
    if fragment.startswith('i'):
        return 0.2
    if fragment.startswith('or'):
        return 0.7
    if fragment.startswith(('oc', 'olic', 'ou', 'ow')):
        return -0.7
    if fragment.startswith(('ec', 'et', 'el', 'efe')):
