        negative = p in ('not', "n't", "'t", 'cannot', 'never')
        return 3.52 if negative else 1.71
    if word == 'see' and t[:1].isspace():
        if p == 'i':
            return 1.98
        if p in ('we', 'you', 'they', 'he', 'she'):
            return 0.41
        return 1.01 if p in ("'t", "n't", 'not', 'cannot') else 0.04
    if word in ('feel', 'hear') and p == 'i':
        return 1.09
    if word in ('sounds', 'sense', 'feels'):
        return 0.11
    if '似' in t:
        return 1.51
    if word in ('觉得', '覺得', '好像'):
        return 0.26
    if t and set(t) == {'·'} and previous and set(previous) == {'·'}:
        return -0.76
    if t == ':' and previous == 'Title' and before in ('', '<|endoftext|>'):
        return -3.98
    if previous.endswith('ส') and t and t[0] in 'ีืั':
        return 1.44
    if not t or not t.isalpha():
        return 0.0

    # Transliteration lets capitalization and Latin diacritics share rules.
    w, q = anyascii(t).lower(), anyascii(previous).lower()
    if w in ('em', 'ems') and q.endswith('se'):
        return 2.54
    if w == 'ical' and q.endswith('ens'):
        return 3.93
    base = unicodedata.normalize('NFD', t)[0]
    if previous.endswith(('σ', 'ς', 'ξ')):
        if base == 'ι':
            return -4.95 if t == base else -2.59
        if base == 'η':
            return -1.12
    if (base in ('α', 'ο', 'ν', 'ς') and previous == 'ι'
            and before.endswith(('σ', 'ξ'))):
        return -1.88
    if t == 'ем' and previous.endswith(('с', 'С')):
        return 2.23
    if not all('LATIN' in unicodedata.name(c, '') for c in t):
        return 0.0

    # Small families of Greco-Latin suffix fragments, not complete words.
    if w in ('ensis', 'esis', 'lesi'):
        return -3.28
    if w in ('esi', 'sis'):
        return -2.34
    if w == 'si':
        return -0.99
    if w in ('asi', 'isi', 'usi', 'ysi'):
        return -0.66
    if w in ('esia', 'esian', 'asia', 'lesia'):
        return -1.12
    if w in ('opsis', 'ysis'):
        return -0.66
    if w not in I_ENDINGS or not q.endswith(('s', 'x')):
        return 0.0

    # The strength depends on the spelling immediately before the ending.
    if t.isupper() and w != 'i':
        return -4.08 if w == 'is' else -1.30
    soft = w in ('ie', 'ion', 'ione', 'ioni', 'ino')
    if q.endswith('es'):
        return -1.93 if soft else -3.74
    if q.endswith('ys'):
        return -2.99
    if q.endswith(('fs', 'ls')):
        return -2.89
    if w == 'i':
        return -0.57
    if soft:
        return -0.34
    return -3.05 if q.endswith(('os', 'ns')) else -1.46


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before = ''
    else:
        _, previous, before = carry
    t = prefix.token_strings[-1]
    return (doc, t, previous), activation(t, previous, before)

"""A sparse spelling-and-formatting detector.

Positive: forms of 'wait' (also completed across tokens), TeX row breaks,
TeX's \\cr, and repeated middle dots. Negative: doubled code escapes,
UTF-8 byte-escape endings, and a 2 attached to a Latin-letter label.
A short text tail distinguishes TeX from code; it resets at document edges.
This deliberately omits most small, token-specific background responses.
"""
import re

READS = ()
TEX = re.compile(
    r'\\(?:begin|end|frac|sqrt|sum|prod|int|lim|hat|vec|overline|'
    r'alpha|beta|gamma|delta|theta|sigma|phi|psi|lambda|mu|eta|'
    r'left|right|quad|nonumber|hfill|color|mathrm|partial|matrix)'
    r'(?![A-Za-z])'
)
WAIT_FORMS = {'wait', 'waits', 'waited', 'waiting'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if history else ''
    word = s.strip().lower()
    tail = history[-4:].lower()
    completed_wait = (
        'wait' not in s.lower() and 'wait' not in tail
        and 'wait' in tail + s.lower()
    )
    p = 0.0
    if word in WAIT_FORMS:
        p = 0.52 if word in {'waited', 'waiting'} else 0.80
        if s == 'Wait':
            p = 0.745
        if prev.strip().lower() in {'but', 'oh', 'well'}:
            p += 0.14
    elif completed_wait:
        p = 1.1
    elif s == 'cr' and history.endswith('\\'):
        p = 3.0 if prev.startswith(' ') else 2.5
    elif s.count('\\') >= 2:
        if TEX.search(history):
            p = 1.4
        elif s.count('\\') > 2:
            p = -0.25
        elif any(q in s.split('\\')[0] for q in "\"'") or prev.endswith('\\"'):
            p = -0.9
        elif prev.endswith('('):
            p = -0.25
        else:
            p = -0.65
    elif s.strip() == '\\' and s.startswith(' ') and prev.count('\\') >= 2:
        p = 0.25
    elif s.isspace() and '\n' in s and prev.count('\\') >= 2:
        if TEX.search(history):
            p = 0.5
    elif s == '2' and re.search(r'\\x[ce]$', history):
        if prev.startswith('\\'):
            p = -0.56
        else:
            p = -0.80 if history.endswith('xc') else -1.29
    elif s == '2' and prev[-1:].isascii() and prev[-1:].isalpha():
        p = -0.25
    elif s == '··' and (not history or history.endswith('··')):
        p = 0.717
    return (doc, (history + s)[-256:]), p
